import React, { useEffect, useState, useRef } from 'react';
import { HelmetProvider } from "react-helmet-async";
import { Link } from 'react-router-dom';
import "../assets/css/Home.css";
import '@fortawesome/fontawesome-free/css/all.css';
import featured_image_2024t3 from '../assets/images/featured_image_relay_result_2024t3.jpg';
import Navbar from '../assets/components/navbar';
import Footer from '../assets/components/footer';
import Papa from "papaparse";

const Home = () => {
  const slideRefs = useRef([]);
  const slideCoverRefs = useRef([]);
  const [players, setPlayers] = useState([]);

  const [files, setFiles] = useState([]);

  useEffect(() => {
    const fetchFileContent = async () => {
      try {
        // Fetch the file from the server
        const response = await fetch(`${process.env.PUBLIC_URL}/data/relay_results_files.txt`);
        if (!response.ok) {
          throw new Error("Failed to fetch file");
        }

        // Read the file content as text
        const content = await response.text();

        // Split the content into lines and trim whitespace
        const lines = content.split('\n').map(line => line.trim());
        setFiles(lines);
        console.log(lines, "File content loaded");
      } catch (error) {
        console.error("Error reading file:", error);
      }
    };

    fetchFileContent();
  }, [])

  useEffect(() => {
    const handleScroll = () => {
      var [ minHeightTop ] = [Infinity];
      const revealingSlide = slideRefs.current.reduce((acc, slide) => {
        if (!slide) return acc;

        const slideRect = slide.getBoundingClientRect();
        const slideTop = slideRect.top;
        const viewportHeight = window.innerHeight;
      
        // Check if the slide is near the center of the viewport
        if (slideTop >= 0 && slideTop <= viewportHeight) {
          if (slideTop < minHeightTop) {
            minHeightTop = slideTop;
            return slide;
          }
        }
        return acc;
      }, null);

      slideRefs.current.forEach(slide => {
        if (!slide) return;
        if (slide != null && slide === revealingSlide) {
          slide.classList.remove("blur-about-us");
          slide.classList.remove("darken-about-us");
          slide.classList.add("lighten-about-us");
        } else {
          slide.classList.add("blur-about-us");
          slide.classList.remove("lighten-about-us");
          slide.classList.add("darken-about-us");
        }
      });

      slideCoverRefs.current.forEach(slide => {
        if (!slide) return;
        if (slide != null && slideRefs.current.indexOf(revealingSlide) === slideCoverRefs.current.indexOf(slide)) {
          slide.classList.remove("blur-about-us");
        } else {
          slide.classList.add("blur-about-us");
        }
      });

    };
  
    window.addEventListener("scroll", handleScroll);
    return () => {
      window.removeEventListener("scroll", handleScroll);
    };
  }, []);
  

  useEffect(() => {
    if (files.length === 0) {
      return
    }
      const convertTimeToSeconds = (time) => {
        // Example: "02:30" -> 150 seconds
        const [minutes, seconds] = String(time).split(":").map(Number);
        return minutes * 60 + seconds;
      };
      const fetchFiles = async () => {
        const results = {};
        const filenames = files;
  
        for (const filename of filenames) {
          const response = await fetch(`${process.env.PUBLIC_URL}/data/${filename}`);
          const text = await response.text();
          
          // Parse CSV content
          const data = Papa.parse(text, { header: true }).data;
  
          // Process data
          const processedData = data.map((row) => ({
            ...row,
            "Time (in sec)": convertTimeToSeconds(row["Time"]),
            Team: parseInt(String(row["Team"]).split(" ")[1]),
          }));
  
          console.log(processedData)
          
          // Store results
          const raceName = filename.split(".")[0].split("relay_results_")[1];
          results[raceName] = processedData;
        }
          
        // Find all unique players
        let allPlayers = [];
        for (const [raceName, playerResults] of Object.entries(results)) {
          for (const result of playerResults) {
            if (!allPlayers.some(player => player.Name == result["Name"])) {
              allPlayers.push(
              {
                Name: result["Name"],
                Gender: result["Gender"],
                Club: "UNSW Campus Runners",
                Group: results["Gender"] === "Female" ? "SW20-24" : "SM20-24",
                Races: [
                  {
                    raceName: raceName,
                    Team: result["Team"],
                    Time: result["Time"],
                    "Time (in sec)": result["Time (in sec)"],
                  }
                ]
              });
            }
            else {
              let player = allPlayers.find(player => player.Name == result["Name"]);
              player.Races.push({
                raceName: raceName,
                Team: result["Team"],
                Time: result["Time"],
                "Time (in sec)": result["Time (in sec)"],
              });
            }
          }
        }
        allPlayers = allPlayers.sort((a, b) => a.Name.localeCompare(b.Name));
        setPlayers(allPlayers);
        console.log(allPlayers);
      };
      fetchFiles();
    }, [files]);
  
  
  return (
    <div>
      <HelmetProvider>
        <title>Home</title>
      </HelmetProvider>
      <div className='section-intro'>
        <Navbar></Navbar>
        <div className='center-texts footer-padding'>
          <div className='intro-preface'>
            <div className='title'>
              <p><span>Your Runs,</span><span>Uncovered.</span></p>
            </div>
            <div className='title-summary'>
              Unlock Your Running Potential with StrideStats.
            </div>
            <div className='signup-box'>
              <Link to='/signup' className='no-underline black'>Sign up</Link>
            </div>
          </div>
          <div className='goals-container'>
            <div className='goals'>
              Analyze your runs, track your progress, and discover insights to help you reach your goals.
            </div>
          </div>
        </div>
        <div className='intro-updates-container'>
          <div className='intro-updates'>
            <div className='title'>
              <span class="line"></span>Featured
            </div>
            <div className='description-container'>
              <img src={featured_image_2024t3} className='featured-image'></img>
              <div className='navigate-update'>
                <div className='date'> 
                  Mon 10/12/2024
                </div>
                <div className='navigate-title'>
                  Relay results for 2024 T3 competition
                </div>
                <Link to='/race/24t3' className='no-underline'>
                  <div className='navigate-link effect1'>
                    View results here
                    <span className="bg"></span>
                  </div>
                </Link>
              </div>
            </div>
          </div>
          <div className='strip-container'>
              <div className='strip'>
                <div className='stats'>
                  <div>{files.length}</div> Total Races
                </div>
                <div className='stats'>
                <div>{players.length}</div> Total Runners
                </div>
                <div className='stats'>
                <div>{files.length}</div> Volunteers
                </div>
              </div>
          </div>
        </div>
      </div>
      <div className="about-us">
        <div className='about-us-information-container'>
          <div className='about-us-information'
            ref={el => slideRefs.current.push(el)}>
            <div className='textbox'>
              StrideStats was born out of a shared passion for running and a desire to help 
              athletes of all levels reach their full potential. Our team is a diverse group of runner who understand the challenges and rewards of the sport. We're dedicated to creating a 
              user-friendly platform that makes it easy to track your runs, analyze your performance, 
              and gain valuable insights to improve your training.
            </div>
          </div>
          <div className='about-us-information'
            ref={el => slideRefs.current.push(el)}>
            <div className='textbox'>
            StrideStats seamlessly captures data from your relay races. 
            Whether you're using a GPS watch or manually entering your splits, 
            StrideStats accurately records your team's performance. Our advanced algorithms 
            then analyze the data to provide insights into each runner's individual performance, 
            team dynamics, and overall race strategy. You can compare your team's results to past races, 
            identify areas for improvement, and gain a deeper understanding of your relay performance.  
          </div>
          </div>          
          <div className='about-us-information'
            ref={el => slideRefs.current.push(el)}>
            <div className='textbox'>
            We believe running is more than just exercise; it's a journey of self-discovery. 
            Our mission is to be your unwavering companion on this journey. We strive to provide you with the tools, insights, and support you need to unlock your full running potential and experience the joy and exhilaration of every stride.
            </div>
          </div>
        </div>
        <div className='about-us-cover'>
          <div className='about-us-cover-title'
            ref={el => slideCoverRefs.current.push(el)}>
            <div>About Us</div>
          </div>
          <div className='about-us-cover-title'
            ref={el => slideCoverRefs.current.push(el)}>
            <div>How it works</div>
          </div>          
          <div className='about-us-cover-title'
            ref={el => slideCoverRefs.current.push(el)}>
            <div>Our mission</div>
          </div>
        </div>
      </div>
      <div className='left-scenic-shot scenic-shot'>
        <div>Let's</div>
      </div>
      <div className='middle-scenic-shot scenic-shot'>
        <div>Run</div>
      </div>
      <div className='right-scenic-shot scenic-shot'>
        <div>Together</div>
      </div>
      <Footer className='remove-footer-margin'></Footer>
    </div>
  );
};

export default Home;