import React from 'react';
import '../css/Navbar.css';
import '@fortawesome/fontawesome-free/css/all.css';
import logo from '../images/logo.webp';
import { Link } from "react-router-dom"

// Define navigation items in a constant for better readability and reusability
const NAV_ITEMS = [
  { path: '/', label: 'Home' },
  { path: '/results', label: 'Results' },
  { path: '/players', label: 'Players' },
  { path: '/login', label: 'Login' },
];

const Navbar = () => {
  return (
    <nav className="navbar">
      {/* Logo */}
      <Link to="/">
        <img src={logo} alt="StrideStats Logo" className="logo" />
      </Link>
      {/* Platform Name */}
      <div className="platform-name-container">
        <div className="platform-name"><Link to="/">StrideStats</Link></div>
      </div>

      {/* Navigation Items */}
      <div className="navbar-items">
        {NAV_ITEMS.map((item, index) => {
          return (
            <Link
              key={index} // Add a unique key for each item
              className="navbar-item"
              to={item.path}
            >
              {item.label}
            </Link>
          );
        })}
      </div>
    </nav>
  );
};

export default Navbar;