import React, { useEffect, useState, useRef } from 'react';
import { HelmetProvider } from 'react-helmet-async';
import { Link } from 'react-router-dom';
import "../assets/css/Results.css";
import '@fortawesome/fontawesome-free/css/all.css';
import Navbar from '../assets/components/navbar';
import SearchGlass from '../assets/images/search_glass.png'
import Papa from "papaparse";
import Footer from '../assets/components/footer';

const Results = () => {

  const [allRelayResults, setAllRelayResults] = useState({});
  const [searchQuery, setSearchQuery] = useState("");
  const [isModalOpen, setIsModalOpen] = useState(false)
  const [modalNo, setModalNo] = useState(0);
  const modalref = useRef(null)
  const [files, setFiles] = useState([]);

  useEffect(() => {
    const fetchFileContent = async () => {
      try {
        // Fetch the file from the server
        const response = await fetch(`${process.env.PUBLIC_URL}/data/relay_results_files.txt`);
        if (!response.ok) {
          throw new Error("Failed to fetch file");
        }

        // Read the file content as text
        const content = await response.text();

        // Split the content into lines and trim whitespace
        const lines = content.split('\n').map(line => line.trim());
        setFiles(lines);
        console.log(lines, "File content loaded");
      } catch (error) {
        console.error("Error reading file:", error);
      }
    };

    fetchFileContent();
  }, [])
  

  const openModal = (no) => {
    setModalNo(no)
    setIsModalOpen(true)
  }

  const closeModal = () => {
    setIsModalOpen(false)
  }

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (isModalOpen && event.target.contains(modalref.current)) {
        if (modalref.current !== event.target) {
          closeModal();
        }
      }
    } 
    window.addEventListener("click", handleClickOutside)
    return () => {
      window.removeEventListener("click", handleClickOutside)
    }
  }, [isModalOpen])

  useEffect(() => {
    const handleKeyPress = (event) => {
      if (event.key === "Escape" && modalref.current) {
        setIsModalOpen(false)
      }
    }
    window.addEventListener("keydown", handleKeyPress)
    return () => {  
      window.removeEventListener("keydown", handleKeyPress)
    } 
  }, [])

  const convertTimeToSeconds = (time) => {
    // Example: "02:30" -> 150 seconds
    const [minutes, seconds] = String(time).split(":").map(Number);
    return minutes * 60 + seconds;
  };
  
  useEffect(() => {
    if (files.length === 0) {
      return
    }
    const fetchFiles = async () => {
      const results = {};
      const filenames = files;

      for (const filename of filenames) {
        const response = await fetch(`${process.env.PUBLIC_URL}/data/${filename}`);
        const text = await response.text();
        
        // Parse CSV content
        const data = Papa.parse(text, { header: true }).data;

        // Process data
        const processedData = data.map((row) => ({
          ...row,
          "Time (in sec)": convertTimeToSeconds(row["Time"]),
          Team: parseInt(String(row["Team"]).split(" ")[1]),
        }));

        console.log(processedData)
        
        // Store results
        const raceName = filename.split(".")[0].split("relay_results_")[1];
        results[raceName] = processedData;
      }

      setAllRelayResults(results);
    };

    fetchFiles();
  }, [files]);


  const handleSortChange = (event) => {
    const sortBy = event.target.value;
    const [sortType, sortOrder] = sortBy.split("-");
  
    // Create a deep copy to avoid mutating the original state
    const sortedResults = Object.entries(allRelayResults).sort(([raceNameA, resultsA], [raceNameB, resultsB]) => {
      let comparison = 0;
  
      if (sortType === "event") {
        comparison = raceNameA.localeCompare(raceNameB);
      } else if (sortType === "finishers") {
        const finishersA = resultsA.length;
        const finishersB = resultsB.length;
        comparison = finishersA - finishersB;
      } else if (sortType === "mff") {
        const maleFirstFinisherA = resultsA
          .filter((row) => row.Gender === "Male")
          .reduce((fastest, current) => {
            return !fastest || current["Time (in sec)"] < fastest["Time (in sec)"]
              ? current
              : fastest;
          }, null);
        const maleFirstFinisherB = resultsB
          .filter((row) => row.Gender === "Male")
          .reduce((fastest, current) => {
            return !fastest || current["Time (in sec)"] < fastest["Time (in sec)"]
              ? current
              : fastest;
          }, null);
        const timeA = maleFirstFinisherA ? maleFirstFinisherA["Time (in sec)"] : Infinity;
        const timeB = maleFirstFinisherB ? maleFirstFinisherB["Time (in sec)"] : Infinity;
        comparison = timeA - timeB;
      } else if (sortType === "fff") {
        const femaleFirstFinisherA = resultsA
          .filter((row) => row.Gender === "Female")
          .reduce((fastest, current) => {
            return !fastest || current["Time (in sec)"] < fastest["Time (in sec)"]
              ? current
              : fastest;
          }, null);
        const femaleFirstFinisherB = resultsB
          .filter((row) => row.Gender === "Female")
          .reduce((fastest, current) => {
            return !fastest || current["Time (in sec)"] < fastest["Time (in sec)"]
              ? current
              : fastest;
          }, null);
        const timeA = femaleFirstFinisherA ? femaleFirstFinisherA["Time (in sec)"] : Infinity;
        const timeB = femaleFirstFinisherB ? femaleFirstFinisherB["Time (in sec)"] : Infinity;
        comparison = timeA - timeB;
      }
  
      // Adjust for ascending or descending order
      return sortOrder === "ascending" ? comparison : -comparison;
    });
  
    // Convert the sorted array back to an object
    const sortedObject = Object.fromEntries(sortedResults);
  
    setAllRelayResults(sortedObject);
  };
  

  // Filter results based on search query
  const filteredRelayResults = Object.entries(allRelayResults).filter(
    ([raceName]) => raceName.toLowerCase().includes(searchQuery.toLowerCase())
  );

  

  return (
    <div>
      <HelmetProvider>
        <title>Results</title>
      </HelmetProvider>
      <Navbar></Navbar>
      <div className='content footer-padding'>
        <div className='title'>Event History</div>
        <div className='search-container'>
          <div className='search-bar'>
            <img src={SearchGlass}></img>
            <input type='text' placeholder='Start typing to search events...' value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)}></input>
          </div>
          <div className='help' onClick={() => {openModal(0)}}>
            ?
          </div>
          <div className="help-modal" style={{ display: isModalOpen ? 'block' : 'none' }}>
              {modalNo == 0 && 
              <div className='modal-content' ref={modalref}>
                <span onClick={closeModal}>&times;</span>
                <div className='modal-text'>
                  <h2>How to search</h2>
                  <div>Use the search box to find events from the event history.</div>
                  <div>Start typing in the box and the matching events will appear in a drop down list</div>
                  <div>To remove the search, click or tap on the X next to the selected option.</div>
                  </div>
              </div>}
          </div>
          <div className='sort'>
            <select className='dropdown' onChange={handleSortChange}>
              <option value='event-ascending'>Sort by Event # ▲</option>
              <option value='event-descending'>Sort by Event # ▼</option>
              <option value='finishers-ascending'>Sort by Finishers ▲</option>
              <option value='finishers-descending'>Sort by Finishers ▼</option>
              <option value='mff-ascending'>Sort by Male First Finishers ▲</option>
              <option value='mff-descending'>Sort by Male First Finishers ▼</option>
              <option value='fff-ascending'>Sort by Female First Finishers ▲</option>
              <option value='fff-descending'>Sort by Female First Finishers ▼</option>
            </select>
          </div>
        </div>
        <div className='column-headers'>
          <div className='small-header'>Event #</div>
          <div className='small-header'>Date</div>
          <div className='small-header'>Finishers</div>
          <div className='small-header'>Volunteers</div>
          <div className='header'>Male First Finishers</div>
          <div className='header'>Female First Finishers</div>
        </div>
      {filteredRelayResults.map(([raceName, results]) => {
        const eventNumber = (Number(raceName.split("t")[0]) - 24) * 3 + (Number(raceName.split("t")[1]))
        const finishers = results.length
        const maleFirstFinisher = results
        .filter((row) => row.Gender === "Male") // Filter for males
        .reduce((fastest, current) => {
          return !fastest || current["Time (in sec)"] < fastest["Time (in sec)"] 
            ? current 
            : fastest;
        }, null);

        // Find the fastest female finisher
        const femaleFirstFinisher = results
        .filter((row) => row.Gender === "Female") // Filter for females
        .reduce((fastest, current) => {
          return !fastest || current["Time (in sec)"] < fastest["Time (in sec)"] 
            ? current 
            : fastest;
        }, null);

        return (
          <div className='column-headers column-entries'>
            <div className='small-header numeric-column'>{eventNumber}</div>
            <div className='small-header'>
            <Link to={`/race/${raceName}`} className="date-link">
              {raceName}
            </Link>
            </div>
            <div className='small-header numeric-column'>{finishers}</div>
            <div className='small-header numeric-column'>{1}</div>
            <div className="header">
            <Link to={`/player/${maleFirstFinisher.Name}`} className="date-link">
              {maleFirstFinisher ? maleFirstFinisher.Name : "N/A"}
            </Link>
              <div className='numeric-column'>{maleFirstFinisher ? maleFirstFinisher.Time : "N/A"}</div>
            </div>
            <div className="header">
              <Link to={`/player/${femaleFirstFinisher.Name}`} className="date-link">
                {femaleFirstFinisher ? femaleFirstFinisher.Name : "N/A"}
              </Link>
              <div className='numeric-column'>{femaleFirstFinisher ? femaleFirstFinisher.Time : "N/A"}</div>
            </div>
          </div>
        )
      })}
      </div>
      <Footer></Footer>
    </div>
  )
}

export default Results;