import React from "react";
import { HelmetProvider } from "react-helmet-async";
import { Link } from "react-router-dom"; // Import Link
import Footer from "../assets/components/footer";
import Navbar from "../assets/components/navbar";
import "../assets/css/LoginPage.css";

const LoginPage = () => {
  return (
    <div>
      <HelmetProvider>
        <title>Login</title>
        <meta name="Login" content="Login" data-react-helmet="true" />
      </HelmetProvider>
      <div className="background-container">
        <Navbar />
        <div className="login-container">
          <div className="login-form">
            <div className="login-form-header">
              <div className="login-title-container">
                <div className="login-title">WELCOME BACK</div>
                <div className="login-subtitle">
                  Welcome back! Please enter your details.
                </div>
              </div>
              <div className="login-form-inputs">
                <div className="login-input-title">Email</div>
                <div className="login-form-input">
                  <input
                    type="text"
                    placeholder="Enter your email"
                    className="login-input"
                  />
                </div>
                <div className="login-input-title">Password</div>
                <div className="login-form-input">
                  <input
                    type="password"
                    placeholder="Password"
                    className="login-input"
                  />
                </div>
                <div className="login-form-extras-container">
                  <div className="login-form-cache-container">
                    <input type="checkbox" className="login-form-cache" />
                    <div className="login-form-cache-text">Remember me</div>
                  </div>
                  <div>Forgot Password</div>
                </div>
                <button className="login-button">Sign in</button>
                <button className="login-button google-login">
                  <div>
                    <a href="/" className="fa-brands fa-google social-media-icons">
                      {" "}
                    </a>
                  </div>
                  <div>Sign in with Google</div>
                </button>
                <div className="login-form-signup-direct-container">
                  <div className="login-form-signup-direct-title">
                    Don't have an account?{" "}
                    <Link to={`/signup`}>Sign up for free!</Link>
                  </div>
                </div>
              </div>
            </div>
          </div>
          <div className="login-form-background"></div>
        </div>
      </div>
      <Footer className="remove-footer-margin" />
    </div>
  );
};

export default LoginPage;