import React, { useEffect, useState, useRef } from 'react';
import { HelmetProvider } from 'react-helmet-async';
import { Link } from 'react-router-dom';
import "../assets/css/Results.css";
import '@fortawesome/fontawesome-free/css/all.css';
import Navbar from '../assets/components/navbar';
import SearchGlass from '../assets/images/search_glass.png'
import Papa from "papaparse";
import Footer from '../assets/components/footer';
import DensityPlot from '../assets/components/DensityPlot';
import BoxPlot from '../assets/components/BoxPlot';

const Players = () => {

  const [allRelayResults, setAllRelayResults] = useState({});
  const [players, setPlayers] = useState([]);
  const [searchQuery, setSearchQuery] = useState("");
  const [isModalOpen, setIsModalOpen] = useState(false)
  const [modalNo, setModalNo] = useState(0);
  const modalref = useRef(null)
  const [activeFilterIndex, setActiveFilterIndex] = useState(0);
  const [files, setFiles] = useState([]);

  useEffect(() => {
    const fetchFileContent = async () => {
      try {
        // Fetch the file from the server
        const response = await fetch(`${process.env.PUBLIC_URL}/data/relay_results_files.txt`);
        if (!response.ok) {
          throw new Error("Failed to fetch file");
        }

        // Read the file content as text
        const content = await response.text();

        // Split the content into lines and trim whitespace
        const lines = content.split('\n').map(line => line.trim());
        setFiles(lines);
        console.log(lines, "File content loaded");
      } catch (error) {
        console.error("Error reading file:", error);
      }
    };

    fetchFileContent();
  }, [])

  const openModal = (no) => {
    setModalNo(no)
    setIsModalOpen(true)
  }

  const closeModal = () => {
    setIsModalOpen(false)
  }

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (isModalOpen && event.target.contains(modalref.current)) {
        if (modalref.current !== event.target) {
          closeModal();
        }
      }
    } 
    window.addEventListener("click", handleClickOutside)
    return () => {
      window.removeEventListener("click", handleClickOutside)
    }
  }, [isModalOpen])

  useEffect(() => {
    const handleKeyPress = (event) => {
      if (event.key === "Escape" && modalref.current) {
        setIsModalOpen(false)
      }
    }
    window.addEventListener("keydown", handleKeyPress)
    return () => {  
      window.removeEventListener("keydown", handleKeyPress)
    } 
  }, [])

  const convertTimeToSeconds = (time) => {
    // Example: "02:30" -> 150 seconds
    const [minutes, seconds] = String(time).split(":").map(Number);
    return minutes * 60 + seconds;
  };
  
  useEffect(() => {
    if (files.length === 0) {
      return
    }
    const fetchFiles = async () => {
      const results = {};
      const filenames = files;

      for (const filename of filenames) {
        const response = await fetch(`${process.env.PUBLIC_URL}/data/${filename}`);
        const text = await response.text();
        
        // Parse CSV content
        const data = Papa.parse(text, { header: true }).data;

        // Process data
        const processedData = data.map((row) => ({
          ...row,
          "Time (in sec)": convertTimeToSeconds(row["Time"]),
          Team: parseInt(String(row["Team"]).split(" ")[1]),
        }));

        console.log(processedData)
        
        // Store results
        const raceName = filename.split(".")[0].split("relay_results_")[1];
        results[raceName] = processedData;
      }

      setAllRelayResults(results);
      
      // Find all unique players
      let allPlayers = [];
      for (const [raceName, playerResults] of Object.entries(results)) {
        for (const result of playerResults) {
          if (!allPlayers.some(player => player.Name == result["Name"])) {
            allPlayers.push(
            {
              Name: result["Name"],
              Gender: result["Gender"],
              Club: "UNSW Campus Runners",
              Group: results["Gender"] === "Female" ? "SW20-24" : "SM20-24",
              Races: [
                {
                  raceName: raceName,
                  Team: result["Team"],
                  Time: result["Time"],
                  "Time (in sec)": result["Time (in sec)"],
                }
              ]
            });
          }
          else {
            let player = allPlayers.find(player => player.Name == result["Name"]);
            player.Races.push({
              raceName: raceName,
              Team: result["Team"],
              Time: result["Time"],
              "Time (in sec)": result["Time (in sec)"],
            });
          }
        }
      }
      allPlayers = allPlayers.sort((a, b) => a.Name.localeCompare(b.Name));
      setPlayers(allPlayers);
      console.log(allPlayers);
    };
    fetchFiles();
  }, [files]);


  const handleSortChange = (event) => {
    const sortBy = event.target.value;
    const [sortType, sortOrder] = sortBy.split("-");

    const sortedObject = [...players].sort((a, b) => { 
      let comparison = 0;
      if (sortType === "name") {
        comparison = a.Name.localeCompare(b.Name);
      } else if (sortType === "numRelays") {
        comparison = a.Races.length - b.Races.length;
      } else if (sortType === "bestTime") {
        const bestTimeA = a.Races.reduce((fastest, current) => {
          return !fastest || current["Time (in sec)"] < fastest["Time (in sec)"]
            ? current
            : fastest;
        }, { "Time (in sec)": Infinity });

        const bestTimeB = b.Races.reduce((fastest, current) => {
          return !fastest || current["Time (in sec)"] < fastest["Time (in sec)"]
            ? current
            : fastest;
        }
        , { "Time (in sec)": Infinity });

        comparison = bestTimeA["Time (in sec)"] - bestTimeB["Time (in sec)"];
      } else if (sortType === "worstTime") {
        const bestTimeA = a.Races.reduce((fastest, current) => {
          return !fastest || current["Time (in sec)"] > fastest["Time (in sec)"]
            ? current
            : fastest;
        }, { "Time (in sec)": 0 });

        const bestTimeB = b.Races.reduce((fastest, current) => {
          return !fastest || current["Time (in sec)"] > fastest["Time (in sec)"]
            ? current
            : fastest;
        }
        , { "Time (in sec)": 0 });

        comparison = bestTimeA["Time (in sec)"] - bestTimeB["Time (in sec)"];
      } else if (sortType === "averageTime") {
        const averageTimeA = a.Races.reduce((acc, current) => {
          return acc + current["Time (in sec)"];
        }, 0) / a.Races.length || 0;

        const averageTimeB = b.Races.reduce((acc, current) => {
          return acc + current["Time (in sec)"];
        }, 0) / b.Races.length || 0;

        comparison = averageTimeA - averageTimeB;
      }
      // Adjust for ascending or descending order
      return sortOrder === "ascending" ? comparison : -comparison;
    });
    
    setPlayers(sortedObject);
  };
  

  // Filter results based on search query
  const filteredPlayers = players.filter(
    (player) =>  String(player.Name).toLowerCase().includes(searchQuery.toLowerCase())
  );

  
  const handleFilterClick = (index) => {
    setActiveFilterIndex(index);
  };
  

  const convertSecondstoTime = (seconds) => {
    const minutes = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${minutes}M ${secs.toString().padStart(2, '0')}s`; 
  }

  const maleTimeData = players.filter((racer) => {
    return racer.Gender === "Male"
  }).map((player) => player.Races).flat().map((p) => p["Time (in sec)"])


  const femaleTimeData = players.filter((racer) => {
    return racer.Gender === "Female"
  }).map((player) => player.Races).flat().map((p) => p["Time (in sec)"])


  const combinedTimeData = players.map((player) => player.Races).flat().map((p) => p["Time (in sec)"])


  return (
    <div>
      <HelmetProvider>
        <title>Players</title>
        <meta name="Players" content="Players" data-react-HelmetProvider="true"/>  
      </HelmetProvider>
      <Navbar></Navbar>
      <div className='content footer-padding'>
        <div className='title'>Players</div>
        <div className='search-container'>
          <div className='search-bar'>
            <img src={SearchGlass}></img>
            <input type='text' placeholder='Start typing to search players...' value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)}></input>
          </div>
          <div className='help' onClick={() => {openModal(0)}}>
            ?
          </div>
          <div className="help-modal" style={{ display: isModalOpen ? 'block' : 'none' }}>
              {modalNo == 0 && 
              <div className='modal-content' ref={modalref}>
                <span onClick={closeModal}>&times;</span>
                <div className='modal-text'>
                  <h2>How to search</h2>
                  <div>Use the search box to find a player from players.</div>
                  <div>Start typing in the box and the matching players will appear in a drop down list</div>
                  <div>To remove the search, click or tap on the X next to the selected option.</div>
                  </div>
              </div>}
          </div>
          <div className='sort'>
            <select className='dropdown' onChange={handleSortChange}>
              <option value='name-ascending'>Sort by Name ▲</option>
              <option value='name-descending'>Sort by Name ▼</option>
              <option value='numRelays-ascending'>Sort by Num Relays ▲</option>
              <option value='numRelays-descending'>Sort by Num Relays ▼</option>
              <option value='bestTime-ascending'>Sort by Best Time ▲</option>
              <option value='bestTime-descending'>Sort by Best Time ▼</option>
              <option value='worstTime-ascending'>Sort by Worst Time ▲</option>
              <option value='worstTime-descending'>Sort by Worst Time ▼</option>
              <option value='averageTime-ascending'>Sort by Average Time ▲</option>
              <option value='averageTime-descending'>Sort by Average Time ▼</option>
            </select>
          </div>
        </div>
        <div className='column-headers'>
          <div className='small-header'>Player #</div>
          <div className='small-header'>Name</div>
          <div className='small-header'>Gender</div>
          <div className='small-header'>Group</div>
          <div className='header club'>Club</div>
          <div className='small-header'>Num Relays</div>
          <div className='small-header time'>Best Time</div>
          <div className='small-header time'>Worst Time</div>
          <div className='small-header time'>Avg Time</div>

        </div>
        {filteredPlayers.map((player, index) => {
          const name = player.Name;
          const gender = player.Gender;
          const group = player.Group;
          const club = player.Club;
          const bestTime = player.Races.reduce((fastest, current) => {
            return !fastest || current["Time (in sec)"] < fastest["Time (in sec)"]
              ? current
              : fastest;
          }, { "Time (in sec)": Infinity });

          const worstTime = player.Races.reduce((slowest, current) => {
            return !slowest || current["Time (in sec)"] > slowest["Time (in sec)"]
              ? current
              : slowest;
          }, { "Time (in sec)": 0 });

          const averageTime = player.Races.reduce((acc, current) => {
            return acc + current["Time (in sec)"];
          }, 0) / player.Races.length || 0;

          const averageTimeMinutes = Math.floor(averageTime / 60);
          const averageTimeSeconds = Math.round(averageTime % 60) < 10 ? "0" + Math.round(averageTime % 60) : Math.round(averageTime % 60);

          const numRelays = player.Races.length;

          return (
            <div className='column-headers column-entries' key={index}>
              <div className='small-header numeric-column'>{index + 1}</div>
              <div className='small-header'>
                <Link to={`/player/${name}`} className="date-link">
                  {name}
                </Link>
              </div>
              <div className='small-header'>{gender}</div>
              <div className='small-header'>{group}</div>
              <div className='header club'>{club}</div>
              <div className='small-header numeric-column'>{numRelays}</div>
              <div className='small-header numeric-column'>{bestTime ? bestTime["Time"] : "N/A"}</div>
              <div className='small-header numeric-column'>{worstTime ? worstTime["Time"] : "N/A"}</div>
              <div className='small-header time numeric-column'>{averageTimeMinutes}:{averageTimeSeconds}</div>
            </div>
          );
        })}
      <div className='subtitle subtitle-after'>Relay Analytics</div>
        <div className='filter-tabs'>
          {['Male', 'Female', 'Combined'].map((label, index) => (
            <div 
              key={index} 
              className={`filter-tab ${index === activeFilterIndex ? 'active-filter-tab' : ''}`} 
              onClick={() => handleFilterClick(index)}
            >
              {label}
            </div>
          ))}
      </div>
      <div className='race-summary-statistics-container'>
        {(() => {

          if (players.length == 0) return;

          // Filter the race data based on the active filter
          const filteredByStatistic =
            activeFilterIndex === 2
              ? players.map((player) => player.Races).flat()
              : players.filter((racer) =>
                  activeFilterIndex === 0 ? racer.Gender === "Male" : racer.Gender === "Female"
                ).map((player) => player.Races).flat();
          
          // Calculate statistics
          const meanTime = Math.floor(
            filteredByStatistic.reduce((sum, curr) => sum + curr["Time (in sec)"], 0) /
              filteredByStatistic.length
          );

          const n = filteredByStatistic.length;

          const middleIndex = Math.floor(n / 2);
          const medianTime = Math.floor(
            n % 2 !== 0
              ? filteredByStatistic[middleIndex]["Time (in sec)"]
              : (filteredByStatistic[middleIndex - 1]["Time (in sec)"] +
                  filteredByStatistic[middleIndex]["Time (in sec)"]) /
                2
              );

          const sdTime = Math.floor(
            Math.sqrt(
              filteredByStatistic.reduce(
                (sum, curr) => sum + (curr["Time (in sec)"] - meanTime) ** 2,
                0
              ) /
                (n - 1)
            ));

            const meanText = [
              "Guide to Mean",
              "The mean here  is the average finishing time of all performances.",
              `It's calculated by summing all times and dividing by the number of performances. (${filteredByStatistic.length})`,
              "The mean helps understand the overall player pace and average player performance."
            ];
            
            const medianText = [
              "Guide to Median",
              "The median relay time is the middle time when all players are ranked.",
              "It's less affected by very fast or slow players than the mean.",
              "The median helps players understand their typical performance."
            ];
            
            const sdText = [
              "Guide to Standard Deviation",
              "Standard deviation measures the spread of relay times across all players.",
              "Higher SD means more varied players times; lower SD means more consistent times.",
              "SD helps understand competition and identify consistently strong/weak players."
            ];

          // Return the mapped JSX
          // Return the mapped JSX
          return [["Mean", meanTime, meanText], ["Median", medianTime, medianText], ["Std Dev", sdTime, sdText]].map(
            (iter, index) => (
              <div key={index} className='summary-statistic-tab'>
                <div className='statistics-title-area'>
                  <div>{iter[0]} Time in Seconds</div>
                  <div
                    className='info-button'
                    onClick={() => openModal(index + 1)} // Set the modalNo dynamically
                  >
                    i
                  </div>
                  {modalNo === index + 1 && isModalOpen && ( // Check if the modal should display for this index
                    <div className='help-modal' style={{ display: 'block' }}>
                      <div className='modal-content' ref={modalref}>
                        <span onClick={closeModal}>&times;</span>
                        <div className='modal-text'>
                          <h2>{iter[2][0]}</h2>
                          <div>{iter[2][1]}</div>
                          <div>{iter[2][2]}</div>
                          <div>{iter[2][3]}</div>
                        </div>
                      </div>
                    </div>
                  )}
                </div>
                <div className='bold-statistic'>{convertSecondstoTime(iter[1])}</div>
              </div>
            )
          );
        })()}
      </div>
      <DensityPlot 
        maleData={maleTimeData}
        femaleData={femaleTimeData} 
        combinedData={combinedTimeData} 
      />
      <div className='race-gender-boxplots'>
        <div className='race-gender-boxplot'>
          <BoxPlot
            data={maleTimeData}
            gender={"Male"}
          />
        </div>
        <div className='race-gender-boxplot'>
          <BoxPlot
            data={femaleTimeData}
            gender={"Female"}
          />
        </div>
      </div>
      </div>
      <Footer></Footer>
    </div>
  )
}

export default Players;