import React from "react";
import { HelmetProvider } from "react-helmet-async";
import { Link } from "react-router-dom"; // Import Link
import Footer from "../assets/components/footer";
import Navbar from "../assets/components/navbar";
import "../assets/css/SignupPage.css";


const Signup = () => {
  const loginPath = `/login`;
  const emptyPath = `..`

  return (
  <div>
    <HelmetProvider>
      <title>Signup</title>
    </HelmetProvider>
    <div className="background-container">
      <Navbar/>
      <div className="signup-container">
        <div className="signup-form-background">
        </div>
        <div className="signup-form">
          <div className="signup-form-header">
            <div className="signup-title-container">
              <div className="login-title">Sign up</div>
              <div className="login-form-signup-direct-title">Already have an account? <Link to={loginPath}>Login here</Link></div> 
            </div>     
            <div className="login-form-inputs">
              <div className="login-input-title">Name</div>
              <div className="login-form-input">
                <input type="text" placeholder="Name" className="login-input" />
              </div>
              <div className="login-input-title">Email</div>
              <div className="login-form-input">
                <input type="text" placeholder="Enter your email" className="login-input" />
              </div>
              <div className="login-input-title">Password</div>
              <div className="login-form-input">
                <input type="password" placeholder="Password" className="login-input" />
              </div>
            </div>
            <div className="signup-form-extras-container">
              <input type="checkbox" className="login-form-cache" />
              <div className="login-form-cache-text">I don't want to receive emails from StrideStats regarding updates.</div>
            </div>
            <div className="terms-and-conditions">
              By creating an account, you agree to StrideStats' <Link to={emptyPath}>Terms of Service</Link> and <Link to={emptyPath}>Privacy Policy</Link>.
            </div>
            <div className="signup-button">
              Sign up
            </div>
          </div>
        </div>
      </div>
    </div>
    <Footer className='remove-footer-margin'/>
  </div>
  )
}

export default Signup;