import React, { useEffect, useState, useRef } from 'react';
import { HelmetProvider } from 'react-helmet-async';
import { Link } from 'react-router-dom';
import "../assets/css/RaceDetails.css";
import '@fortawesome/fontawesome-free/css/all.css';
import Navbar from '../assets/components/navbar';
import SearchGlass from '../assets/images/search_glass.png'
import Papa from "papaparse";
import { useParams } from 'react-router-dom';
import Footer from '../assets/components/footer';
import DensityPlot from '../assets/components/DensityPlot';
import BoxPlot from '../assets/components/BoxPlot';
import { MathComponent } from 'mathjax-react';
import Simulation from '../assets/components/Simulation';


const RaceDetails = () => {

  const { raceName } = useParams();
  const [allRelayResults, setAllRelayResults] = useState({});
  const [raceData, setRaceData] = useState([]);
  const [searchQuery, setSearchQuery] = useState("");
  const [teamQuery, setTeamQuery] = useState("");
  const [teamData, setTeamData] = useState([]);
  const [isModalOpen, setIsModalOpen] = useState(false)

  const [modalNo, setModalNo] = useState(0);

  const modalref = useRef(null)
  const [activeFilterIndex, setActiveFilterIndex] = useState(0);
  const [files, setFiles] = useState([]);
  
  useEffect(() => {
    const fetchFileContent = async () => {
      try {
        // Fetch the file from the server
        const response = await fetch(`${process.env.PUBLIC_URL}/data/relay_results_files.txt`);
        if (!response.ok) {
          throw new Error("Failed to fetch file");
        }

        // Read the file content as text
        const content = await response.text();

        // Split the content into lines and trim whitespace
        const lines = content.split('\n').map(line => line.trim());
        setFiles(lines);
        console.log(lines, "File content loaded");
      } catch (error) {
        console.error("Error reading file:", error);
      }
    };

    fetchFileContent();
  }, [])
  

  const openModal = (no) => {
    setModalNo(no)
    setIsModalOpen(true)
  }

  const closeModal = () => {
    setIsModalOpen(false)
  }

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (isModalOpen && event.target.contains(modalref.current)) {
        if (modalref.current !== event.target) {
          closeModal();
        }
      }
    } 
    window.addEventListener("click", handleClickOutside)
    return () => {
      window.removeEventListener("click", handleClickOutside)
    }
  }, [isModalOpen])

  useEffect(() => {
    const handleKeyPress = (event) => {
      if ((event.key === "Escape" && modalref.current)) {
        setIsModalOpen(false)
      }
    }
    window.addEventListener("keydown", handleKeyPress)
    return () => {  
      window.removeEventListener("keydown", handleKeyPress)
    } 
  }, [])

  const convertTimeToSeconds = (time) => {
    // Example: "02:30" -> 150 seconds
    const [minutes, seconds] = String(time).split(":").map(Number);
    return minutes * 60 + seconds;
  };

  const convertSecondstoTime = (seconds) => {
    const minutes = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${minutes}M ${secs.toString().padStart(2, '0')}s`; 
  }

  const convertSecondstoTimeColon = (seconds) => {
    const minutes = Math.floor(seconds / 60);
    const minutesString = minutes < 10 ? `0${minutes}` : minutes
    const secs = seconds % 60;
    const secsString = secs < 10 ? `0${secs}` : secs
    return `${minutesString}:${secsString}`
  }

  useEffect(() => {
    if (files.length === 0) {
      return
    }
    const fetchFiles = async () => {
      const results = {};
      const filenames = files;

      for (const filename of filenames) {
        const response = await fetch(`${process.env.PUBLIC_URL}/data/${filename}`);
        const text = await response.text();
        
        // Parse CSV content
        const data = Papa.parse(text, { header: true }).data;

        // Process data
        const processedData = data.map((row) => ({
          ...row,
          "Time (in sec)": convertTimeToSeconds(row["Time"]),
          Cluster: parseInt(String(row["Cluster"])) + 1,
          Team: parseInt(String(row["Team"]).split(" ")[1]),
        }));

        console.log(processedData)
        
        // Store results
        const raceName = filename.split(".")[0].split("relay_results_")[1];
        results[raceName] = processedData;
      }

      setAllRelayResults(results);
      const initialRaceData = results[raceName].sort((a, b) => a["Time (in sec)"] - b["Time (in sec)"]);
      setRaceData(initialRaceData)

      const teamsArray = Object.values(
        initialRaceData.reduce((acc, curr) => {
          acc[curr.Team] = acc[curr.Team] ?? []
          acc[curr.Team].push(curr);
          return acc
        }, {})
      )

      const largestTeamSize = teamsArray.reduce((acc, curr) => {
        if (curr.length > acc) {
          return curr.length
        }
        return acc
      }, 0)

      const adjustTeamTime = (team) => {
        const teamTime = team.reduce((acc, curr) => curr["Time (in sec)"] + acc, 0)
        const teamSize = team.length
        const averagePlayerTime = teamTime / teamSize
        return Math.floor(teamTime + (largestTeamSize - teamSize) * averagePlayerTime)
      }


      const initialTeamData = teamsArray.map((teamResults) => {
        const totalTime = adjustTeamTime(teamResults)
        const numRunners = teamResults.length
        const numMales = teamResults.reduce((sum, curr) => curr.Gender === "Male" ? sum + 1 : sum, 0)
        const numFemales = teamResults.reduce((sum, curr) => curr.Gender === "Female" ? sum + 1 : sum, 0)
        const time = convertSecondstoTimeColon(totalTime)
        const clusterSum = teamResults.reduce((sum, curr) => sum + curr["Cluster"], 0)

        const mean = teamsArray.reduce((sum, curr) => sum + adjustTeamTime(curr), 0) / numRunners
        const sd = Math.sqrt(teamsArray.reduce((sum, curr) => sum  + (adjustTeamTime(curr) - mean) ** 2, 0) / (numRunners - 1))
        const zScore = (totalTime - mean) / sd


        const expectedClusterSum = largestTeamSize * (largestTeamSize + 1)/2 / largestTeamSize
        const differenceClusterSum = largestTeamSize - (clusterSum) / expectedClusterSum
        const clusterScore = Math.abs(differenceClusterSum / expectedClusterSum)
        console.log(expectedClusterSum, differenceClusterSum, clusterSum, "cluster score")
        
        const balanceScore = Math.abs(zScore) + clusterScore
        console.log(totalTime, mean, sd, zScore, clusterScore, "Balance score")

        const times = teamResults.map((team) => {
          return {
            time: team["Time (in sec)"], 
            name: team.Name,
            position: team.Position
          }
          }
        ).sort((a, b) => parseInt(a.position) - parseInt(b.position))

        return {
          Team: teamResults[0].Team,
          NumRunners: numRunners,
          NumMales: numMales,
          NumFemales: numFemales,
          "Time (in sec)": totalTime,
          Time: time,
          ClusterSum: clusterSum,
          BalanceScore: balanceScore,
          times: times
        }
      }).sort((a, b) => {
        return a["Time (in sec)"] - b["Time (in sec)"]
      })
      console.log(initialTeamData)      

      setTeamData(initialTeamData)
    };

    fetchFiles();
  }, [files]);


  const handleTeamSortChange = (event) => {
    const sortBy = event.target.value;
    const [sortType, sortOrder] = sortBy.split("-");
    const sortedObject = [...teamData].sort((a, b) => {
      let comparison = 0
      if (sortType === "team") {
        comparison = a.Team - b.Team;
      }
      else if (sortType === "time") {
        comparison = a["Time (in sec)"] - b["Time (in sec)"]
      }
      else if (sortType === "numRunners") {
        comparison = a.NumRunners - b.NumRunners
      }
      else if (sortType === "malenumRunners") {
        comparison = a.NumMales - b.NumMales
      }
      else if (sortType === "femalenumRunners") {
        comparison = a.NumFemales - b.NumFemales
      }
      else if (sortType === "balanceScore") {
        comparison = a.BalanceScore - b.BalanceScore;
      }
      return sortOrder === "ascending" ? comparison : -comparison;
    });
    setTeamData(sortedObject);
  }

  const handleSortChange = (event) => {
    const sortBy = event.target.value;
    const [sortType, sortOrder] = sortBy.split("-");
    const sortedObject = [...raceData].sort((a, b) => {
      let comparison = 0
      if (sortType === "position") {
        comparison = a["Time (in sec)"] - b["Time (in sec)"];
      }
      else if (sortType === "relays") {
        const numParkrunsA = Object.entries(allRelayResults).filter(([nameRace, data]) => {
          return data.filter((racer) => racer.Name === a.Name).length > 0 
          && 
          nameRace.localeCompare(raceName) <= 0;
        }).length;

        const numParkrunsB = Object.entries(allRelayResults).filter(([nameRace, data]) => {
          return data.filter((racer) => racer.Name === b.Name).length > 0 
          && 
          nameRace.localeCompare(raceName) <= 0;
        }).length;

        comparison = numParkrunsA - numParkrunsB;
        console.log(numParkrunsA, numParkrunsB)
      }
      else if (sortType === "team") {
        comparison = a.Team - b.Team;
      }

      else if (sortType === "racePosition") {
        comparison = a.Position - b.Position;
      }

      return sortOrder === "ascending" ? comparison : -comparison;
    });
    setRaceData(sortedObject);
  };
  

  const filteredPlayerResults = raceData.filter(
    (racer) =>  String(racer.Name).toLowerCase().includes(searchQuery.toLowerCase())
  );

  const filteredTeamResults = teamData.filter(
    (team) => String(team.Team).toLowerCase().includes(teamQuery.toLowerCase())
  )


  const eventNumber = (Number(raceName.split("t")[0]) - 24) * 3 + (Number(raceName.split("t")[1]))

  const maleTimeData = raceData.filter((racer) => {
    return racer.Gender === "Male"
  }).map((racer) => {
    return racer["Time (in sec)"]
  })

  const femaleTimeData = raceData.filter((racer) => {
    return racer.Gender === "Female"
  }).map((racer) => {
    return racer["Time (in sec)"]
  })


  const combinedTimeData = raceData.map((racer) => {
    return racer["Time (in sec)"]
  })


  const handleFilterClick = (index) => {
    setActiveFilterIndex(index);
  };

  // teamData
  //           .sort((a, b) => parseInt(a.Team) - parseInt(b.Team))
  //           .map((team, index) => {
  //             const relayTeamColors = [
  //               "#FF9980", // Lighter Orange
  //               "#80D8B6", // Lighter Green
  //               "#85B8FF", // Lighter Blue
  //               "#FFF380", // Lighter Yellow
  //               "#C678DD", // Lighter Purple
  //               "#FFB6D9", // Lighter Pink
  //               "#80CBC4"  // Lighter Teal
  //             ];

  //             const largestTeamSize = teamData.reduce((acc, curr) => {
  //               if (curr.length > acc) {
  //                 return curr.length
  //               }
  //               return acc
  //             }, 0)

  //             const times = team.times.length == largestTeamSize ? team.times : [...team.times, team.times.reduce((sum, curr) => sum + curr.time) / largestTeamSize]


  return (
    <div>
      <HelmetProvider>
        <title>{raceName ? `Race - ${raceName}` : "Race Details"}</title>
      </HelmetProvider>
      <Navbar></Navbar>
      <div className='content footer-padding'>
        <div className='title'>Relay Results</div>
        <div className='subtitle'>{raceName} <span>|</span> #{eventNumber}</div>
        <div className='search-container'>
          <div className='search-bar'>
            <img src={SearchGlass}></img>
            <input type='text' placeholder='Start typing to search players...' value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)}></input>
          </div>
          <div className='help' onClick={() => {openModal(0)}}>
            ?
          </div>
          {modalNo === 0 && isModalOpen && ( 
            <div className="help-modal" style={{display: 'block'}}>
              <div className='modal-content' ref={modalref}>
                <span onClick={closeModal}>&times;</span>
                <div className='modal-text'>
                  <h2>How to search</h2>
                  <div>Use the search box to find relay runners within the current relay.</div>
                  <div>Start typing in the box and the matching relay runners will appear in a drop down list</div>
                  <div>To remove the search, click or tap on the X next to the selected option.</div>
                  </div>
              </div>
            </div>
          )}
          <div className='sort'>
            <select className='dropdown' onChange={handleSortChange}>
              <option value='position-ascending'>Sort by Position ▲</option>
              <option value='position-descending'>Sort by Position ▼</option>
              <option value='relays-ascending'>Sort by Relays Ran ▲</option>
              <option value='relays-descending'>Sort by Relays Ran ▼</option>
              <option value='team-ascending'>Sort by Team ▲</option>
              <option value='team-descending'>Sort by Team ▼</option>
              <option value='racePosition-ascending'>Sort by Race Position ▲</option>
              <option value='racePosition-descending'>Sort by Race Position ▼</option>
            </select>
          </div>
        </div>
        <div className='column-headers'>
          <div className='small-header'>Position</div>
          <div className='small-header'>Name</div>
          <div className='small-header'>Gender</div>
          <div className='small-header'>Group</div>
          <div className='small-header'>Team</div>
          <div className='header club'>Club</div>
          <div className='small-header'>Race Position</div>
          <div className='small-header time'>Time</div>
        </div>
      {filteredPlayerResults.map((racer) => {
        const name = racer.Name;
        const time = racer.Time;
        const racePos = racer.Position
        const gender = racer.Gender;
        const ageGroup = gender == "Male" ? "SM20-24" : "SW20-24";
        const position = [...raceData].sort((a, b) => a["Time (in sec)"] - b["Time (in sec)"]).indexOf(racer) + 1;
        const numParkruns = Object.entries(allRelayResults).filter(([nameRace, data]) => {
          return data.filter((racer) => racer.Name === name).length > 0 
          && 
          nameRace.localeCompare(raceName) <= 0;
        }).length;
        const genderPosition = [...raceData].sort((a, b) => a["Time (in sec)"] - b["Time (in sec)"]).filter((racer) => racer.Gender === gender).indexOf(racer) + 1;
        const numberofParticularGender = [...raceData].filter((racer) => racer.Gender === gender).length;
        const personalBest = Object.entries(allRelayResults).reduce((acc, [nameRace, data], index) => {
          const personalBestTime = data.filter((r) => r.Name === name)[0];
          if (personalBestTime && personalBestTime["Time (in sec)"] < acc["Time (in sec)"] && 
            nameRace.localeCompare(raceName) <= 0) {
            return {
              "Time (in sec)": personalBestTime["Time (in sec)"],
              "Time": personalBestTime["Time"],
              "index": index
            };
          }
          return acc;
        }, {"Time (in sec)": Infinity, "Time": Infinity, "index": Infinity });

        const team = racer.Team
        var personalBestString = "";
        var color = "orange";
        if (numParkruns === 1) {
          personalBestString = "First Timer!";
          color = "#7ac248";
        }
        else if (personalBest["Time (in sec)"] === racer["Time (in sec)"] && personalBest["index"] === eventNumber - 1) {
          personalBestString = "New PB!";
          color = "#df1745";
        }
        else {
          personalBestString = "PB: " + personalBest["Time"];
          color = "grey"
        }

        return (
          <div className='column-headers column-entries'>
            <div className='small-header position numeric-column'>{position}</div>
            <div className='small-header'>
              <Link to={`/player/${name}`} className="date-link">
                {name}
              </Link>
              <div className='sub-information'>{numParkruns} relays</div>
            </div>
            <div className='small-header'>
              <div>{gender}</div>
              <div className='sub-information'>
                {genderPosition}/{numberofParticularGender}
              </div>
            </div>
            <div className='small-header'>{ageGroup}</div>
            <div className='small-header'>{team}</div>
            <div className='header club'>UNSW Campus Runners</div>
            <div className='small-header'>{racePos}</div>
            <div className='small-header time numeric-column'>
              <div>{time}</div>
              <div className='sub-information' style={{color: color}}>{personalBestString}</div>
            </div>
          </div>
        )
      })}
      <div className='subtitle subtitle-after'>Team Results</div>
      <div className='search-container'>
          <div className='search-bar'>
            <img src={SearchGlass}></img>
            <input type='text' placeholder='Start typing to search teams...' value={teamQuery} onChange={(e) => setTeamQuery(e.target.value)}></input>
          </div>
          <div className='help' onClick={() => {openModal(1)}}>
            ?
          </div>
          {modalNo === 1 && isModalOpen && ( 
            <div className="help-modal" style={{display: 'block'}}>
              <div className='modal-content' ref={modalref}>
                <span onClick={closeModal}>&times;</span>
                <div className='modal-text'>
                  <h2>How to search</h2>
                  <div>Use the search box to find teams.</div>
                  <div>Start typing in the box and the matching team will appear in a drop down list</div>
                  <div>To remove the search, click or tap on the X next to the selected option.</div>
                </div>
              </div>
            </div>
          )}
          <div className='sort'>
            <select className='dropdown' onChange={handleTeamSortChange}>
              <option value='time-ascending'>Sort by Time ▲</option>
              <option value='time-descending'>Sort by Time ▼</option>
              <option value='team-ascending'>Sort by Team ▲</option>
              <option value='team-descending'>Sort by Team ▼</option>
              <option value='balanceScore-ascending'>Sort by Balance Score ▲</option>
              <option value='balanceScore-descending'>Sort by Balance Score ▼</option>
              <option value='numRunners-ascending'>Sort by Number of Runners ▲</option>
              <option value='numRunners-descending'>Sort by Number of Runners ▼</option>
              <option value='malenumRunners-ascending'>Sort by Male Runners ▲</option>
              <option value='malenumRunners-descending'>Sort by Male Runners ▼</option>
              <option value='femalenumRunners-ascending'>Sort by Female Runners ▲</option>
              <option value='femalenumRunners-descending'>Sort by Female Runners ▼</option>
            </select>
          </div>
        </div>
        <div className='column-headers'>
          <div className='small-header'>Position</div>
          <div className='small-header'>Team</div>
          <div className='small-header'>Male Runners</div>
          <div className='small-header'>Female Runners</div>
          <div className='small-header'>Number of Runners</div>
          <div className='small-header'>Balance Score</div>
          <div className='small-header time'>Time</div>
        </div>
      {filteredTeamResults.map((team) => {
        const position = [...teamData].sort((a, b) => a["Time (in sec)"] - b["Time (in sec)"]).indexOf(team) + 1;
        const name = team.Team
        const time = team.Time
        const numRunners = team.NumRunners
        const numMales = team.NumMales
        const numFemales = team.NumFemales
        const balanceScore = team.BalanceScore

        var personalisedString = "";
        var color = "orange";

        if (position === 1) {
          personalisedString = "First Place!";
          color = "#7ac248";
        }
        else {
          const higherPos = [...teamData].sort((a, b) => a["Time (in sec)"] - b["Time (in sec)"])[position - 1 - 1]
          const timeDifference = team["Time (in sec)"] - higherPos["Time (in sec)"]
          personalisedString = `+${convertSecondstoTime(timeDifference)}`;
          color = "#df1745";
        }
        return (
          <div className='column-headers column-entries'>
            <div className='small-header position numeric-column'>{position}</div>
            <div className='small-header'>{name}</div>
            <div className='small-header'>{numMales}</div>
            <div className='small-header'>{numFemales}</div>
            <div className='small-header'>{numRunners}</div>
            <div className='small-header'>{balanceScore.toFixed(2)}</div>
            <div className='small-header time numeric-column'>
              <div>{time}</div>
              <div className='sub-information' style={{color: color}}>{personalisedString}</div>
            </div>
          </div>
        )
      })}
      {teamData.length > 0 && 
        <div className='race-summary-statistics-container' style={{marginTop: "5vh"}}>
          <div className='summary-statistic-tab'>
            <div className='statistics-title-area'>
              <div>Overall Balance Score</div>
              <div
                className='info-button'
                onClick={() => openModal(2)} // Set the modalNo dynamically
              >
                i
              </div>
              {modalNo === 2 && isModalOpen && ( // Check if the modal should display for this index
                <div className='help-modal' style={{ display: 'block' }}>
                  <div className='modal-content' ref={modalref}>
                    <span onClick={closeModal}>&times;</span>
                    <div className='modal-text'>
                      <h2>What is a Balance Score?</h2>
                      <div className='typesetting'><MathComponent tex='Let\:T = \{t_1, t_2, t_3, \dots, t_m\} \text{ be a set of teams, }' display={true}/></div>
                      <div className='typesetting'><MathComponent tex='t_i = \{r_1, r_2, r_3, \dots, r_n\} \text{ be a set of runners.}' display={true}/></div>
                      <div className='typesetting'><MathComponent tex='Balance\:Score = \frac{1}{m} \sum_{i=1}^m(\vert \tilde{z_i} \vert + \vert n - \frac{\sum_{j=1}^n r_{ij}.\tilde{cluster}}{l}\vert)' display={true}/></div>
                      <div className='typesetting'><MathComponent tex='where\: \tilde{z}\:is\:the\:sample\:z\:score\:for\:team\:time\:and\:l = \frac{1 + \max_{t \in T} \vert t \vert}{2}' display={true}/></div>
                    </div>
                  </div>
                </div>
              )}
            </div>
          <div className='bold-statistic'>
            {
              (teamData.reduce((sum, curr) => sum + curr.BalanceScore, 0)/teamData.length).toFixed(2)
            }
          </div>
        </div>
      </div>}
      <div className='subtitle subtitle-after'>Relay Analytics</div>
        <div className='filter-tabs'>
          {['Male', 'Female', 'Combined'].map((label, index) => (
            <div 
              key={index} 
              className={`filter-tab ${index === activeFilterIndex ? 'active-filter-tab' : ''}`} 
              onClick={() => handleFilterClick(index)}
            >
              {label}
            </div>
          ))}
      </div>
      <div className='race-summary-statistics-container'>
        {(() => {

          // Filter the race data based on the active filter
          const filteredByStatistic =
            activeFilterIndex === 2
              ? raceData
              : raceData.filter((racer) =>
                  activeFilterIndex === 0 ? racer.Gender === "Male" : racer.Gender === "Female"
                );
          
          if (filteredByStatistic.length == 0) return;
          
          // Calculate statistics
          const meanTime = Math.floor(
            filteredByStatistic.reduce((sum, curr) => sum + curr["Time (in sec)"], 0) /
              filteredByStatistic.length
          );

          const n = filteredByStatistic.length;

          const middleIndex = Math.floor(n / 2);
          const medianTime = Math.floor(
            n % 2 !== 0
              ? filteredByStatistic[middleIndex]["Time (in sec)"]
              : (filteredByStatistic[middleIndex - 1]["Time (in sec)"] +
                  filteredByStatistic[middleIndex]["Time (in sec)"]) /
                2
              );

          const sdTime = Math.floor(
            Math.sqrt(
              filteredByStatistic.reduce(
                (sum, curr) => sum + (curr["Time (in sec)"] - meanTime) ** 2,
                0
              ) /
                (n - 1)
            ));

            const meanText = [
              "Guide to Mean",
              "The mean here  is the average finishing time of all players.",
              `It's calculated by summing all times and dividing by the number of players. (${filteredByStatistic.length})`,
              "The mean helps understand the overall player pace and average player performance."
            ];
            
            const medianText = [
              "Guide to Median",
              "The median relay time is the middle time when all players are ranked.",
              "It's less affected by very fast or slow players than the mean.",
              "The median helps players understand their typical performance."
            ];
            
            const sdText = [
              "Guide to Standard Deviation",
              "Standard deviation measures the spread of relay times across all players.",
              "Higher SD means more varied players times; lower SD means more consistent times.",
              "SD helps understand competition and identify consistently strong/weak players."
            ];

          // Return the mapped JSX
          // Return the mapped JSX
          return [["Mean", meanTime, meanText], ["Median", medianTime, medianText], ["Std Dev", sdTime, sdText]].map(
            (iter, index) => (
              <div key={index} className='summary-statistic-tab'>
                <div className='statistics-title-area'>
                  <div>{iter[0]} Time in Seconds</div>
                  <div
                    className='info-button'
                    onClick={() => openModal(index + 3)} // Set the modalNo dynamically
                  >
                    i
                  </div>
                  {modalNo === index + 3 && isModalOpen && ( // Check if the modal should display for this index
                    <div className='help-modal' style={{ display: 'block' }}>
                      <div className='modal-content' ref={modalref}>
                        <span onClick={closeModal}>&times;</span>
                        <div className='modal-text'>
                          <h2>{iter[2][0]}</h2>
                          <div>{iter[2][1]}</div>
                          <div>{iter[2][2]}</div>
                          <div>{iter[2][3]}</div>
                        </div>
                      </div>
                    </div>
                  )}
                </div>
                <div className='bold-statistic'>{convertSecondstoTime(iter[1])}</div>
              </div>
            )
          );
        })()}
      </div>
      <DensityPlot 
        maleData={maleTimeData}
        femaleData={femaleTimeData} 
        combinedData={combinedTimeData} 
      />
      <div className='race-gender-boxplots'>
        <div className='race-gender-boxplot'>
          <BoxPlot
            data={maleTimeData}
            gender={"Male"}
          />
        </div>
        <div className='race-gender-boxplot'>
          <BoxPlot
            data={femaleTimeData}
            gender={"Female"}
          />
        </div>
      </div>
      <div className='subtitle'>Relay Simulation</div>
      {teamData.length > 0 && <Simulation teamData={teamData}></Simulation>}
      </div>
      <Footer></Footer>
    </div>
  )
}

export default RaceDetails;