import React from 'react';
import "../css/Footer.css";
import '@fortawesome/fontawesome-free/css/all.css';
import logo from '../images/logo.webp';
import {Link} from "react-router-dom"

const Footer = ({ className }) => {
  const emptyPath = ""

  return (
    <div>
      <footer className={`footer ${className || ''}`}>
        <div className='footer-items'>
          <div className='footer-item'>
            <div className="footer-item-main">
              <div>
                <div className='footer-item-title'>
                  StrideStats
                </div>
                <div className='footer-item-description'>
                  Unlock Your Running Potential
                </div>
              </div>
              <img src={logo} alt="StrideStats Logo" className="logo" />
            </div>
            <div className='footer-item-socials'>
              <Link to={emptyPath} className="fa-brands fa-linkedin social-media-icons"></Link>
              <Link to={emptyPath} className="fa-brands fa-discord social-media-icons"></Link>
              <Link to={emptyPath} className="fa-brands fa-instagram social-media-icons"></Link>
              <Link to={emptyPath} className="fa-brands fa-facebook social-media-icons"></Link>
            </div>
          </div>
          <div className='footer-item-links'>
            <a>About Us</a>
            <a>Contact Us</a>
            <a>Privacy Policy</a>
            <a>Terms of Service</a>
          </div>
          <div className='footer-item'>
            <div>Sign up to StrideStats</div>
            <div className='footer-item-email'>
              <input type='text' placeholder='Email Address'></input>
              <button>Submit</button>
            </div>
          </div>
        </div>
        <div>© StrideStats Inc.</div>
      </footer>
    </div>
  )
}

export default Footer;