import React, {useRef, useEffect} from "react";
import { Chart, registerables } from "chart.js";
import "../css/DensityPlot.css"

Chart.register(...registerables);

const DensityPlot = ({ maleData, femaleData, combinedData }) => {
  const chartRef = useRef(null);

  useEffect(() => {
    // Generate density data points using a KDE function (or precomputed densities).
    const calculateKDE = (data, range, bandwidth = 20) => {
      const kernel = (x) => Math.exp(-0.5 * (x ** 2)) / Math.sqrt(2 * Math.PI); // Gaussian kernel
      return range.map((x) => ({
        x,
        y: data.reduce((sum, value) => sum + kernel((x - value) / bandwidth), 0) / (data.length * bandwidth),
      }));
    };

    // Example: Generate KDE data

    const maxRange = combinedData.length != 0 ? combinedData.reduce((acc, curr) => acc > curr ? acc : curr) * 3 : 2000
    const range = Array.from({ length: maxRange }, (_, i) => i / 2); // Adjust range as needed
    const maleDensity = calculateKDE(maleData, range);
    const femaleDensity = calculateKDE(femaleData, range);
    const combinedDensity = calculateKDE(combinedData, range);

    // Destroy existing chart if exists
    if (chartRef.current) chartRef.current.destroy();

    // Create new chart
    chartRef.current = new Chart(document.getElementById("densityPlot"), {
      type: "line",
      data: {
        datasets: [
          {
            label: "Male",
            data: maleDensity,
            borderColor: "#1f77b4",
            backgroundColor: "rgba(31, 119, 180, 0.5)",
            borderWidth: 2,
            fill: true,
          },
          {
            label: "Female",
            data: femaleDensity,
            borderColor: "#e74c3c",
            backgroundColor: "rgba(231, 76, 60, 0.5)",
            borderWidth: 2,
            fill: true,
          },
          {
            label: "Combined",
            data: combinedDensity,
            borderColor: "#2ecc71",
            backgroundColor: "rgba(46, 204, 113, 0.5)",
            borderWidth: 2,
            fill: true,
          },
        ],
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            display: true,
            position: "top",
            labels: {
              color: "#fff"
            }
          },
          title: {
            display: true,
            color: '#fff',
            text: "Density Plot of Time (in sec) for Male, Female, and Combined",
          },
        },
        scales: {
          x: {
            ticks: {
              color: '#fff'
            },
            type: "linear",
            title: {
              display: true,
              text: "Time (in sec)",
              color: '#fff'
            },
          },
          y: {
            ticks: {
              color: '#fff'
            },
            title: {
              display: true,
              text: "Density",
              color: '#fff'
            },
          },
        },
      },
    });
  }, [maleData, femaleData, combinedData]);

  return (
    <div className="density-plot-dimensions">
      <canvas id="densityPlot"></canvas>
    </div>
  );
};

export default DensityPlot;
