import React, { useEffect, useState } from "react";
import { isEqual, update } from 'lodash';
import "../css/RaceDetails.css";

const Simulation = ({ teamData }) => {
  const largestTeamSize = Math.max(...teamData.map((team) => team.times.length));

  const [animationStart, setAnimationStart] = useState(false)
  const [pauseState, setPauseState] = useState(false)
  const [animationSpeedUp, setAnimationSpeedUp] = useState(1)
  const [updatedIndex, setUpdatedIndex] = useState(null)


  const beginAnimation = () => {
      if (animationDurations.every((team) => {
      return team.finished
    })) {
      setAnimationDurations(normalizedTeamData.map((team) => ({
        durations: team.times,
        currentIndex: 0,
        finished: false,
      })))
      setClocks(normalizedTeamData.map((team) => {
        return {
          durations: team.times,
          progress: 0,
          rank: "--",
          currentTime: 0,
          name: team.Team,
        }
      }))
      setUpdatedIndex(null)
    }
    setAnimationStart(true)
    setPauseState(false)
  } 

  const pauseAnimation = () => {
    if (!animationStart) {
      beginAnimation()
      return 
    }
    console.log(animationDurations)
    console.log(animationStart)
    setAnimationStart(false)
    setPauseState(true)
  }

  const stopAnimation = () => {
    Array.from(Array(teamData.length).keys()).map((i) => {
      const teamElement = document.querySelector(`.team-icon[data-team="${i}"]`);
      if (teamElement) {
        teamElement.classList.add("animation-reset");
        void teamElement.offsetWidth; // Trigger a reflow for pseudo-element animations
        teamElement.classList.remove("animation-reset");
      }
    })
    setAnimationStart(false)
    setAnimationDurations(normalizedTeamData.map((team) => ({
      durations: team.times,
      currentIndex: 0,
      finished: false,
    })))
    setClocks(normalizedTeamData.map((team) => {
      return {
        durations: team.times,
        progress: 0,
        rank: "--",
        currentTime: 0,
        name: team.Team,
      }
    }))
    setUpdatedIndex(null)
  }

  const speedUpAnimation = () => {
    setAnimationSpeedUp(animationSpeedUp * 2)
    console.log("SPEED UP", animationSpeedUp)
  }

  const slowDownAnimation = () => {
    setAnimationSpeedUp(animationSpeedUp * 0.5)
    console.log("Slow UP", animationSpeedUp)
  }

  // Normalize times for all teams
  const normalizedTeamData = teamData.map((team) => ({
    ...team,
    times:
      team.times.length === largestTeamSize
        ? team.times
        : [
            ...team.times,
            {
              time: team.times.reduce((sum, curr) => sum + curr.time, 0) / team.times.length,
              name: `Team ${team.Team} filler`
            },
          ],
  })).sort((a, b) => parseInt(a.Team) - parseInt(b.Team));

  const [animationDurations, setAnimationDurations] = useState(
    normalizedTeamData.map((team) => ({
      durations: team.times,
      currentIndex: 0,
      finished: false,
    }))
  );

  const [clocks, setClocks] = useState(
    normalizedTeamData.map((team) => {
      return {
        durations: team.times,
        progress: 0,
        rank: "--",
        currentTime: 0,
        name: team.Team,
      }
    })
  )

  const convertSecondstoTimeColon = (seconds) => {
    const minutes = Math.floor(seconds / 60);
    const minutesString = minutes < 10 ? `0${minutes}` : minutes
    const secs = seconds % 60;
    const secsString = secs < 10 ? `0${secs}` : secs
    return `${minutesString}:${secsString}`
  }

  const convertToRank = (rank) => {
    return rank == 1 ? `${rank}st` : rank == 2 ? `${rank}nd` : rank == 3 ? `${rank}rd` : `${rank}th`
  }

  // useEffect(() => {
  //   if (!animationDurations || animationDurations.length === 0) return;
  
  //   const timeouts = animationDurations.map(({ durations, currentIndex }, teamIndex) => {
  //     const timeoutDuration = durations[currentIndex].time  * 1000 / 40;
  //     console.log("Timeout duration:", timeoutDuration);
  
  //     return setTimeout(() => {
  //       setAnimationDurations((prev) => {
  //         console.log(prev, "Here")
  //         return prev.map((teamAnimation, index) => {
  //           if (index !== teamIndex) return teamAnimation;
  //           const nextIndex = (teamAnimation.currentIndex + 1) % teamAnimation.durations.length;
  //           return { ...teamAnimation, currentIndex: nextIndex };
  //         })
  //       }
  //       );
  //     }, timeoutDuration);
  //   });
  
  //   return () => timeouts.forEach((timeout) => clearTimeout(timeout));
  // }, [animationDurations]);
  

  useEffect(() => {
    if (!animationStart) return; // Pause animation if animationStart is false
  
    if (!animationDurations || animationDurations.length === 0) return;
    let updateIndex = null;
    if ((animationDurations.every((team) => {
      return team.finished
    }))) {
      Array.from(Array(teamData.length).keys()).map((i) => {
        const teamElement = document.querySelector(`.team-icon[data-team="${i}"]`);
        if (teamElement) {
          teamElement.classList.add("animation-reset");
          void teamElement.offsetWidth; // Trigger a reflow for pseudo-element animations
          teamElement.classList.remove("animation-reset");
        }
      })
      return;
    }
  
    const interval = setInterval(() => {
      const newAnimationDurations = animationDurations.map((teamAnimation, teamIndex) => {
        const { durations, currentIndex } = teamAnimation;
        // if (durations.length === currentIndex + 1) {
        //   return { ...teamAnimation, finished: true };
        // }
        const nextIndex =
          clocks[0].currentTime >=
          durations.reduce(
            (sum, curr, index) => (index <= currentIndex ? curr.time + sum : sum),
            0
          )
            ? (currentIndex + 1)
            : currentIndex;
        if (nextIndex === currentIndex + 1 && durations.length !== nextIndex) {
          // setUpdatedIndex(teamIndex)
          updateIndex = teamIndex
        }

        if (durations.length === nextIndex) {
          return { ...teamAnimation, finished: true };
        }
        

        return { ...teamAnimation, currentIndex: nextIndex };
      })
      // if (!isEqual(animationDurations, newAnimationDurations)) {
      //   setAnimationDurations(newAnimationDurations)
      // }
      if (updateIndex != null) {
        setUpdatedIndex(updateIndex)
        setAnimationDurations(newAnimationDurations)
      }
      else if (!isEqual(animationDurations, newAnimationDurations)) {
        setAnimationDurations(newAnimationDurations)
      }
      // setAnimationDurations((prev) =>
      //   prev.map((teamAnimation) => {
      //     const { durations, currentIndex } = teamAnimation;
      //     if (durations.length === currentIndex + 1) {
      //       return { ...teamAnimation, finished: true };
      //     }
  
      //     const nextIndex =
      //       clocks[0].currentTime >=
      //       durations.reduce(
      //         (sum, curr, index) => (index <= currentIndex ? curr.time + sum : sum),
      //         0
      //       )
      //         ? (currentIndex + 1) % durations.length
      //         : currentIndex % durations.length;
          
  
      //     return { ...teamAnimation, currentIndex: nextIndex };
      //   })
      // );
    }, 1000 / (40 * animationSpeedUp)); // Adjust interval timing with speed
  
    return () => clearInterval(interval); // Cleanup interval on unmount or dependency change
  }, [animationStart, animationSpeedUp, clocks]);
  

  useEffect(() => {
    if (!animationStart) return;
    if (!animationDurations || animationDurations.length === 0) return;
    if ((animationDurations.every((team) => {
      return team.finished
    }))) {
      Array.from(Array(teamData.length).keys()).map((i) => {
        const teamElement = document.querySelector(`.team-icon[data-team="${i}"]`);
        if (teamElement) {
          teamElement.classList.add("animation-reset");
          void teamElement.offsetWidth; // Trigger a reflow for pseudo-element animations
          teamElement.classList.remove("animation-reset");
        }
      })
      return;
    }
    // const updatedTeamIndex = animationDurations.findIndex(
    //   (teamAnimation, index) =>
    //     teamAnimation.currentIndex !==
    //     animationDurations[index]?.currentIndex
    // );

    if (updatedIndex === null) return; // No update needed

    const teamElement = document.querySelector(`.team-icon[data-team="${updatedIndex}"]`);
    if (teamElement) {
      const { currentIndex } = animationDurations[updatedIndex];

      const currentDuration = animationDurations[updatedIndex].durations[currentIndex];
      const animationTime = currentDuration.time / (40 * animationSpeedUp);
  
      // Reset and reapply animation
      teamElement.style.animation = "none"; // Stop the current animation
      void teamElement.offsetWidth; // Trigger a reflow to restart the animation
      teamElement.style.animation = `moveAroundBorder ${animationTime}s linear infinite`;

          // Update CSS variables for pseudo-elements to reset their animation
      teamElement.classList.add("animation-reset");
      void teamElement.offsetWidth; // Trigger a reflow for pseudo-element animations
      teamElement.classList.remove("animation-reset");

    }
    
  }, [updatedIndex, animationStart, animationSpeedUp]);
  


  useEffect(() => {
    if (!animationStart) return;
    if (!animationDurations || animationDurations.length === 0) return;
    if ((animationDurations.every((team) => {
      return team.finished
    }))) {
      return;
    }
    const interval = setInterval(() => {
        setClocks((prevClocks) => {
            return prevClocks.map((clock, clockIndex) => {
                const nextTime = clock.currentTime + 1;
                if (clock.progress >= clock.durations.length) {
                    return clock; // No updates if progress is complete
                }

                const updatedProgress = clock.durations
                    .map((i) => i.time)
                    .reduce((sumObj, curr) => {
                        if (sumObj.finished) return sumObj;

                        if (sumObj.timeSum + curr < nextTime) {
                            return {
                                ...sumObj,
                                progressSum: sumObj.progressSum + 1,
                                timeSum: sumObj.timeSum + curr,
                            };
                        } else {
                            return {
                                ...sumObj,
                                progressSum: sumObj.progressSum + (nextTime - sumObj.timeSum) / ( curr || 1),
                                timeSum: sumObj.timeSum + curr,
                                finished: true,
                            };
                        }
                    }, { progressSum: 0, timeSum: 0, finished: false });

                const updatedRank =
                    prevClocks.length - prevClocks.filter((c) => c.name !== clock.name && c.progress < updatedProgress.progressSum).length;

                return {
                    ...clock,
                    progress: updatedProgress.progressSum,
                    currentTime: nextTime,
                    rank: updatedRank,
                };
            });
        });
    }, 1000 / (40 * animationSpeedUp));

    return () => clearInterval(interval);
}, [animationStart, animationSpeedUp]);


  return (
    <div>       
    <div className="simulation">
      <div className="track-marking1"></div>
      <div className="track-marking2"></div>
      <div className="track-marking3"></div>
      <div className="starting-line"></div>
      <div className="team-scoreboard">
        {normalizedTeamData.map((team, teamIndex) => {
          const teamAnimation = animationDurations[teamIndex];
          const currentIndex = teamAnimation.currentIndex;
          const currentDuration = teamAnimation.durations[currentIndex];
          const currentName = currentDuration.name

          const progress = clocks[teamIndex].progress
          return (
            <div className="team-score">
              <div>Position {currentIndex + 1}</div>
              <div style={{color: "#f1d5a2"}}>{currentName}</div>
              <div style={{color:"#17ee56"}}>{progress.toFixed(2)}</div>
            </div>
          )
        })}
      </div>
      {normalizedTeamData.map((team, teamIndex) => {
        const teamAnimation = animationDurations[teamIndex];
        const currentIndex = teamAnimation.currentIndex;
        const currentDuration = teamAnimation.durations[currentIndex];
        const finishedAnimation = teamAnimation.finished;

        const colors = [
          "#FF9980", // Lighter Orange
          "#80D8B6", // Lighter Green
          "#85B8FF", // Lighter Blue
          "#FFF380", // Lighter Yellow
          "#C678DD", // Lighter Purple
          "#FFB6D9", // Lighter Pink
          "#80CBC4", // Lighter Teal
        ];

        const backgroundColor = colors[teamIndex % colors.length];

        const animationDuration = currentDuration.time / (40 * animationSpeedUp);

        const animationStyle =
          animationStart && !finishedAnimation && !pauseState
            ? { animation: `moveAroundBorder ${animationDuration}s linear infinite` }
            : !finishedAnimation && pauseState
            ? { animation: `moveAroundBorder ${animationDuration}s linear infinite`, "animation-play-state": "paused" }
            : null;
          
        const startTransitionAnimation = animationStart && !finishedAnimation && !pauseState ? "running" : "paused"
        
        return (
          <div
            key={team.Team}
            className="team-icon"
            data-team={teamIndex} // Add data attribute
            style={{
              backgroundColor,
              "--team-border-color": backgroundColor, // Pass the color to pseudo-elements
              "--team-animation-duration": `${animationDuration}s`, // Dynamic animation duration
              "--team-startTransitionTransition": `${startTransitionAnimation}`,
              ...animationStyle
            }}
          >
            <div className="team-icon-tooltip">
              <div className="tooltip-text">Position {currentIndex + 1}</div>
              <div className="tooltip-text">{currentDuration.name}</div>
            </div>
          </div>
        );
      })}

      </div>
      <div className='teams-display-container'>
        <div className='teams-display'>
          {normalizedTeamData
            .map((team, index) => {
              const relayTeamColors = [
                "#FF9980", // Lighter Orange
                "#80D8B6", // Lighter Green
                "#85B8FF", // Lighter Blue
                "#FFF380", // Lighter Yellow
                "#C678DD", // Lighter Purple
                "#FFB6D9", // Lighter Pink
                "#80CBC4"  // Lighter Teal
              ];

              return (
                <div 
                  key={team.Team} 
                  className='team-display' 
                  style={{ backgroundColor: relayTeamColors[index % relayTeamColors.length] }}
                >
                  Team {index + 1}
                  <div className='team-time'>
                    {convertSecondstoTimeColon(clocks.filter((clock) => clock.name === team.Team)[0].currentTime)}
                  </div>
                  <div className='team-rank'>
                    {convertToRank(clocks.filter((clock) => clock.name === team.Team)[0].rank)}
                  </div>
                </div>
              );
            })}
        </div>
      </div>
      <div className='simulation-controls-container'>
        <div className='simulation-controls'>
          {[
            { icon: '▶', onClick: beginAnimation },
            { icon: '❚❚', onClick: pauseAnimation },
            { icon: '■', onClick: stopAnimation },
            { icon: 'x2', onClick: speedUpAnimation },
            { icon: 'x0.5', onClick: slowDownAnimation },
          ].map(({ icon, onClick }) => (
            <div key={icon} className="simulation-control" onClick={onClick}>
              {icon}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Simulation;
