import React, { useState } from "react";
import { Line } from "react-chartjs-2";
import {
  Chart as ChartJS,
  LineElement,
  CategoryScale,
  LinearScale,
  Title,
  Tooltip,
  Legend,
} from "chart.js";

ChartJS.register(LineElement, CategoryScale, LinearScale, Title, Tooltip, Legend);

const LinearReg = (playerData) => {
  // Linear regression implementation
  const linearRegression = (x, y) => {
    const n = x.length;
    const sumX = x.reduce((acc, val) => acc + val, 0);
    const sumY = y.reduce((acc, val) => acc + val, 0);
    const sumXY = x.reduce((acc, val, i) => acc + val * (y[i] - sumY/n), 0);
    const sumX2 = x.reduce((acc, val) => acc + val * (val - sumX/n), 0);

    const slope = sumXY / sumX2;
    const intercept = (sumY - slope * sumX) / n;

    return { slope, intercept };
  };

  let i = 0;
  const data = playerData["playerData"].reduce((obj, curr) => {
  
    obj.times.push(curr["Time (in sec)"]);
    obj.relays.push(`Relay ${i + 1}`);
    i += 1;
  
    return obj;
  }, { 
    times: [],
    relays: []
  }); 

  
  // Perform linear regression to predict future times
  const { times, relays } = data;
  const timeIndices = times.map((_, i) => i + 1);

  const regression = linearRegression(timeIndices, times);
  const futureIndices = Array.from({ length: 3 }, (_, i) => timeIndices.length + i + 1);
  const futurePredictions = futureIndices.map((x) => regression.slope * x + regression.intercept);

  return (
    <div>
      {(
        <div>
          <Line
            data={{
              labels: relays,
              datasets: [
                {
                  label: "Past Performance",
                  data: times,
                  borderColor: "#57b9ff",
                  borderWidth: 2,
                },
              ],
            }}
            options={{
              responsive: true,
              plugins: {
                legend: {
                  position: "top",
                  labels: {
                    color: "#fff", // Make legend text white
                  },
                },
                title: {
                  display: true,
                  text: "Past Performance",
                  color: "#fff", // Make title text white
                },
                tooltip: {
                  callbacks: {
                    label: function (context) {
                      const seconds = context.raw; // Retrieve the raw data point value
                      const minutes = Math.floor(seconds / 60);
                      const remainingSeconds = Math.floor(seconds % 60);
                      const formattedTime = `${minutes}m ${remainingSeconds}s`;
                      return `Time: ${formattedTime}`; // Custom tooltip label
                    },
                  },
                },
              },
              scales: {
                x: {
                  title: {
                    display: true,
                    text: "Relays", // Label for the x-axis
                    color: "#fff", // Make x-axis label text white
                    font: {
                      size: 14, // Font size for x-axis label
                    },
                  },
                  ticks: {
                    color: "#fff", // Make x-axis labels white
                  },
                },
                y: {
                  title: {
                    display: true,
                    text: "Time (in seconds)", // Label for the y-axis
                    color: "#fff", // Make y-axis label text white
                    font: {
                      size: 14, // Font size for y-axis label
                    },
                  },
                  ticks: {
                    color: "#fff", // Make y-axis labels white
                  },
                },
              },
            }}
          />

          <Line
            data={{
              labels: [
                ...relays,
                ...futurePredictions.map((_, i) => `Relay ${relays.length + i + 1}`),
              ],
              datasets: [
                {
                  label: "Past Performance",
                  data: times,
                  borderColor: "#57b9ff",
                  borderWidth: 2,
                },
                {
                  label: "Predicted Performance",
                  data: [...times, ...futurePredictions],
                  borderColor: "#ff4500",
                  borderDash: [5, 5],
                  borderWidth: 2,
                },
              ],
            }}
            options={{
              responsive: true,
              plugins: {
                legend: {
                  position: "top",
                  labels: {
                    color: "#fff", // Make legend text white
                  },
                },
                title: {
                  display: true,
                  text: "Past Performance + Performance Predictions",
                  color: "#fff", // Make title text white
                },
                tooltip: {
                  callbacks: {
                    label: function (context) {
                      const seconds = context.raw; // Retrieve the raw data point value
                      const minutes = Math.floor(seconds / 60);
                      const remainingSeconds = Math.floor(seconds % 60);
                      const formattedTime = `${minutes}m ${remainingSeconds}s`;
                      return `Time: ${formattedTime}`; // Custom tooltip label
                    },
                  },
                },
              },
              scales: {
                x: {
                  title: {
                    display: true,
                    text: "Relays", // Label for the x-axis
                    color: "#fff", // Make x-axis label text white
                    font: {
                      size: 14, // Font size for x-axis label
                    },
                  },
                  ticks: {
                    color: "#fff", // Make x-axis labels white
                  },
                },
                y: {
                  title: {
                    display: true,
                    text: "Time (in seconds)", // Label for the y-axis
                    color: "#fff", // Make y-axis label text white
                    font: {
                      size: 14, // Font size for y-axis label
                    },
                  },
                  ticks: {
                    color: "#fff", // Make y-axis labels white
                  },
                },
              },
            }}
          />
        </div>
      )}
    </div>
  );
};

export default LinearReg;
