import React, { useEffect, useState, useRef } from 'react';
import { HelmetProvider } from 'react-helmet-async';
import { Link } from 'react-router-dom';
import "../assets/css/Player.css";
import '@fortawesome/fontawesome-free/css/all.css';
import Navbar from '../assets/components/navbar';
import Footer from '../assets/components/footer';
import SearchGlass from '../assets/images/search_glass.png'
import Papa from "papaparse";
import { useParams } from 'react-router-dom';
import LinearReg from '../assets/components/LinearReg';

const Player = () => {

  const { playerName } = useParams();
  const [player, setPlayer] = useState({});
  const [playerResults, setPlayerResults] = useState([]);
  const [allRelayResults, setAllRelayResults] = useState({});
  const [searchQuery, setSearchQuery] = useState("");
  const [isModalOpen, setIsModalOpen] = useState(false)
  const [modalNo, setModalNo] = useState(0);
  const modalref = useRef(null)
  const [activeFilterIndex, setActiveFilterIndex] = useState(0);
  const [files, setFiles] = useState([]);

  useEffect(() => {
    const fetchFileContent = async () => {
      try {
        // Fetch the file from the server
        const response = await fetch(`${process.env.PUBLIC_URL}/data/relay_results_files.txt`);
        if (!response.ok) {
          throw new Error("Failed to fetch file");
        }

        // Read the file content as text
        const content = await response.text();

        // Split the content into lines and trim whitespace
        const lines = content.split('\n').map(line => line.trim());
        setFiles(lines);
        console.log(lines, "File content loaded");
      } catch (error) {
        console.error("Error reading file:", error);
      }
    };

    fetchFileContent();
  }, [])

  const openModal = (no) => {
    setModalNo(no)
    setIsModalOpen(true)
  }

  const closeModal = () => {
    setIsModalOpen(false)
  }

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (isModalOpen && event.target.contains(modalref.current)) {
        if (modalref.current !== event.target) {
          closeModal();
        }
      }
    } 
    window.addEventListener("click", handleClickOutside)
    return () => {
      window.removeEventListener("click", handleClickOutside)
    }
  }, [isModalOpen])

  useEffect(() => {
    const handleKeyPress = (event) => {
      if (event.key === "Escape" && modalref.current) {
        setIsModalOpen(false)
      }
    }
    window.addEventListener("keydown", handleKeyPress)
    return () => {  
      window.removeEventListener("keydown", handleKeyPress)
    } 
  }, [])

  const convertTimeToSeconds = (time) => {
    // Example: "02:30" -> 150 seconds
    const [minutes, seconds] = String(time).split(":").map(Number);
    return minutes * 60 + seconds;
  };
  
  useEffect(() => {
    if (files.length === 0) {
      return
    }
    const fetchFiles = async () => {
      const results = {};
      const filenames = files;

      for (const filename of filenames) {
        const response = await fetch(`${process.env.PUBLIC_URL}/data/${filename}`);
        const text = await response.text();
        
        // Parse CSV content
        const data = Papa.parse(text, { header: true }).data;

        // Process data
        const processedData = data.map((row) => ({
          ...row,
          "Time (in sec)": convertTimeToSeconds(row["Time"]),
          Team: parseInt(String(row["Team"]).split(" ")[1]),
        }));

        console.log(processedData)
        
        // Store results
        const raceName = filename.split(".")[0].split("relay_results_")[1];
        results[raceName] = processedData;
      }

      setAllRelayResults(results);
      
      // Find all unique players
      let allPlayers = [];
      for (const [raceName, playerResults] of Object.entries(results)) {
        for (const result of playerResults) {
          if (!allPlayers.some(player => player.Name == result["Name"])) {
            allPlayers.push(
            {
              Name: result["Name"],
              Gender: result["Gender"],
              Club: "UNSW Campus Runners",
              Group: results["Gender"] === "Female" ? "SW20-24" : "SM20-24",
              Races: [
                {
                  raceName: raceName,
                  Team: result["Team"],
                  Time: result["Time"],
                  "Time (in sec)": result["Time (in sec)"],
                  position: parseInt(result["Position"]),
                }
              ]
            });
          }
          else {
            let player = allPlayers.find(player => player.Name == result["Name"]);
            player.Races.push({
              raceName: raceName,
              Team: result["Team"],
              Time: result["Time"],
              "Time (in sec)": result["Time (in sec)"],
              position: parseInt(result["Position"]),
            });
          }
        }
      }
      allPlayers = allPlayers.sort((a, b) => a.Name.localeCompare(b.Name));
      const targetPlayer = allPlayers.find(player => player.Name === playerName)
      console.log(targetPlayer, "TARGET PLAYER")
      setPlayer(targetPlayer);
      setPlayerResults(targetPlayer.Races);
    };
    fetchFiles();
  }, [files]);


  const handleSortChange = (event) => {
    const sortBy = event.target.value;
    const [sortType, sortOrder] = sortBy.split("-");

    const sortedObject = [...playerResults].sort((a, b) => { 
      let comparison = 0;
      if (sortType === "event") {
        const raceNameA = a.raceName;
        const raceNameB = b.raceName;
        comparison = raceNameA.localeCompare(raceNameB);
      } else if (sortType === "numRelays") {
        comparison = a.Races.length - b.Races.length;
      } else if (sortType === "position") {
        const positionA = allRelayResults[a.raceName].sort((x, y) => x["Time (in sec)"] - y["Time (in sec)"]).findIndex((racer) => racer.Name === playerName) + 1;
        const positionB = allRelayResults[b.raceName].sort((x, y) => x["Time (in sec)"] - y["Time (in sec)"]).findIndex((racer) => racer.Name === playerName) + 1;
        comparison = positionA - positionB;
      } else if (sortType === "genderPosition") {
        const genderPositionA = allRelayResults[a.raceName].filter((racer) => racer.Gender == player.Gender).sort((a, b) => a["Time (in sec)"] - b["Time (in sec)"]).findIndex((racer) => racer.Name === playerName) + 1;
        const genderPositionB = allRelayResults[b.raceName].filter((racer) => racer.Gender == player.Gender).sort((a, b) => a["Time (in sec)"] - b["Time (in sec)"]).findIndex((racer) => racer.Name === playerName) + 1;
        comparison = genderPositionA - genderPositionB;
      } else if (sortType === "time") {
        comparison = a["Time (in sec)"] - b["Time (in sec)"];
      }
      else if (sortType === "percentile") {
        const totalRunnersA = allRelayResults[a.raceName].length;
        const totalRunnersB = allRelayResults[b.raceName].length;
        const positionA = allRelayResults[a.raceName].sort((x, y) => x["Time (in sec)"] - y["Time (in sec)"]).findIndex((racer) => racer.Name === playerName) + 1;
        const positionB = allRelayResults[b.raceName].sort((x, y) => x["Time (in sec)"] - y["Time (in sec)"]).findIndex((racer) => racer.Name === playerName) + 1;
        const percentileA = positionA / totalRunnersA * 100;
        const percentileB = positionB / totalRunnersB * 100;
        comparison = percentileA - percentileB;
      }
      else if (sortType === "genderPercentile") {
        const totalGenderRunnersA = allRelayResults[a.raceName].filter((racer) => racer.Gender == player.Gender).length;
        const totalGenderRunnersB = allRelayResults[b.raceName].filter((racer) => racer.Gender == player.Gender).length;
        const genderPositionA = allRelayResults[a.raceName].filter((racer) => racer.Gender == player.Gender).sort((a, b) => a["Time (in sec)"] - b["Time (in sec)"]).findIndex((racer) => racer.Name === playerName) + 1;
        const genderPositionB = allRelayResults[b.raceName].filter((racer) => racer.Gender == player.Gender).sort((a, b) => a["Time (in sec)"] - b["Time (in sec)"]).findIndex((racer) => racer.Name === playerName) + 1;
        const genderPercentileA = genderPositionA / totalGenderRunnersA * 100;
        const genderPercentileB = genderPositionB / totalGenderRunnersB * 100;
        comparison = genderPercentileA - genderPercentileB;
      }  
      else if (sortType === "racePosition") {
        comparison = a.position - b.position
      }
      return sortOrder === "ascending" ? comparison : -comparison;
    });
    
    setPlayerResults(sortedObject);
  };

  

  // Filter results based on search query
  const filteredPlayerResults = playerResults.filter(
    (race) =>  race.raceName.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const convertSecondstoTime = (seconds) => {
    const minutes = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${minutes}M ${secs.toString().padStart(2, '0')}s`; 
  }

  
  const handleFilterClick = (index) => {
    setActiveFilterIndex(index);
  };
  

  return (
    <div>
      <HelmetProvider>
        <title>{player ? player.Name : "Player"}</title>
      </HelmetProvider>
      <Navbar></Navbar>
      <div className='content footer-padding'>
        <div className='title'>{playerName}</div>
        <div className='subtitle'>Past results</div>
        <div className='search-container'>
          <div className='search-bar'>
            <img src={SearchGlass}></img>
            <input type='text' placeholder='Start typing to search events...' value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)}></input>
          </div>
          <div className='help' onClick={() => {openModal(0)}}>
            ?
          </div>
          <div className="help-modal" style={{ display: isModalOpen ? 'block' : 'none' }}>
              {modalNo == 0 && 
              <div className='modal-content' ref={modalref}>
                <span onClick={closeModal}>&times;</span>
                <div className='modal-text'>
                  <h2>How to search</h2>
                  <div>Use the search box to find an event from the relay history.</div>
                  <div>Start typing in the box and the matching events will appear in a drop down list</div>
                  <div>To remove the search, click or tap on the X next to the selected option.</div>
                  </div>
              </div>}
          </div>
          <div className='sort'>
            <select className='dropdown' onChange={handleSortChange}>
              <option value='event-ascending'>Sort by Event # ▲</option>
              <option value='event-descending'>Sort by Event # ▼</option>
              <option value='position-ascending'>Sort by Position ▲</option>
              <option value='position-descending'>Sort by Position ▼</option>
              <option value='racePosition-ascending'>Sort by Race Position ▲</option>
              <option value='racePosition-descending'>Sort by Race Position ▼</option>
              <option value='percentile-ascending'>Sort by Percentile ▲</option>
              <option value='percentile-descending'>Sort by Percentile ▼</option>
              <option value='genderPosition-ascending'>Sort by Gender Position ▲</option>
              <option value='genderPosition-descending'>Sort by Gender Position ▼</option>
              <option value='genderPercentile-ascending'>Sort by Gender Percentile ▲</option>
              <option value='genderPercentile-descending'>Sort by Gender Percentile ▼</option>
              <option value='time-ascending'>Sort by Time ▲</option>
              <option value='time-descending'>Sort by Time ▼</option>
            </select>
          </div>
        </div>
        <div className='column-headers'>
          <div className='small-header'>Event #</div> 
          <div className='small-header'>Date</div>
          <div className='small-header'>Group</div>
          <div className='header club'>Club</div>
          <div className='small-header'>Race Pos</div>
          <div className='small-header'>Position</div>
          <div className='small-header'>%</div>
          <div className='small-header'>Gender Pos</div>
          <div className='small-header'>Gender %</div>
          <div className='small-header time'>Time</div>
        </div>
      {filteredPlayerResults.map((result) => {
        const raceName = result.raceName;
        const time = result.Time;
        const personalBest = Object.entries(allRelayResults).reduce((acc, [nameRace, data]) => {
          const personalBestTime = data.filter((r) => r.Name === playerName)[0];
          if (personalBestTime && personalBestTime["Time (in sec)"] < acc["Time (in sec)"] && 
            nameRace.localeCompare(raceName) <= 0) {
            return personalBestTime;
          }
          return acc;
        }, { "Time (in sec)": Infinity });

        const numParkruns = Object.entries(allRelayResults).filter(([nameRace, data]) => {
          return data.filter((racer) => racer.Name === playerName).length > 0 
          && 
          nameRace.localeCompare(raceName) <= 0;
        }).length;

        var personalBestString = "";
        var color = "orange";
        if (numParkruns === 1) {
          personalBestString = "First Timer!";
          color = "#7ac248";
        }
        else if (personalBest["Time (in sec)"] === result["Time (in sec)"]) {
          personalBestString = "New PB!";
          color = "#df1745";
        }
        else {
          personalBestString = "PB: " + personalBest["Time"];
          color = "grey"
        }


        const eventNumber = (Number(raceName.split("t")[0]) - 24) * 3 + (Number(raceName.split("t")[1]))
        const group = player.Group;
        const club = player.Club;
        const totalRunners = allRelayResults[raceName].length;
        const totalGenderRunners = allRelayResults[raceName].filter((racer) => racer.Gender == player.Gender).length;
        const position = allRelayResults[raceName].sort((a, b) => a["Time (in sec)"] - b["Time (in sec)"]).findIndex((racer) => racer.Name === playerName) + 1;
        const genderPosition = allRelayResults[raceName].filter((racer) => racer.Gender == player.Gender).sort((a, b) => a["Time (in sec)"] - b["Time (in sec)"]).findIndex((racer) => racer.Name === playerName) + 1;
        
        const percentile = position / totalRunners * 100;
        const percentileString = percentile.toFixed(2) + "%";

        const genderPercentile = genderPosition / totalGenderRunners * 100;
        const genderPercentileString = genderPercentile.toFixed(2) + "%";

        const racePos = result.position
        const playerTeam =  allRelayResults[raceName].filter((racer) => racer.Name == player.Name)[0].Team
        const numRunners = allRelayResults[raceName].filter((racer) => racer.Team === playerTeam).length
        
        return (
          <div className='column-headers column-entries'>
            <div className='small-header numeric-column'>{eventNumber}</div>
            <Link className='small-header no-underline' to={`/race/${raceName}`}>{raceName}</Link>
            <div className='small-header'>{group}</div>
            <div className='header club'>{club}</div>
            <div className='small-header numeric-column'>{racePos} / {numRunners}</div>
            <div className='small-header numeric-column'>{position} / {totalRunners}</div>
            <div className='small-header numeric-column'>{percentileString}</div>
            <div className='small-header numeric-column'>{genderPosition} / {totalGenderRunners}</div>
            <div className='small-header numeric-column'>{genderPercentileString}</div>
            <div className='small-header time numeric-column'>
              <div>{time}</div>
              <div className='sub-information' style={{color: color}}>{personalBestString}</div>
            </div>
          </div>
        );
      })}
      <div className='subtitle subtitle-after'>Player Analytics</div>
        <div className='filter-tabs'>
          {['Fastest', 'Mean', 'Slowest'].map((label, index) => (
            <div 
              key={index} 
              className={`filter-tab ${index === activeFilterIndex ? 'active-filter-tab' : ''}`} 
              onClick={() => handleFilterClick(index)}
            >
              {label}
            </div>
          ))}
      </div>
      <div className='race-summary-statistics-container'>
        {(() => {
        const currFilter =  ['Fastest', 'Mean', 'Slowest'][activeFilterIndex]
        let time, position, genderPos, text;
          if (currFilter == "Fastest") {
            time = playerResults.reduce((fastest, curr) => fastest > curr["Time (in sec)"] ? curr["Time (in sec)"] : fastest, Number.MAX_SAFE_INTEGER)
            position = playerResults.reduce((fastest, curr) => {
              const currPos = allRelayResults[curr.raceName].sort((a, b) => a["Time (in sec)"] - b["Time (in sec)"]).findIndex((racer) => racer.Name === playerName) + 1
              return fastest > currPos ? currPos : fastest
            }, Number.MAX_SAFE_INTEGER)

            genderPos = playerResults.reduce((fastest, curr) => {
              const currPos = allRelayResults[curr.raceName].filter((racer) => racer.Gender == player.Gender).sort((a, b) => a["Time (in sec)"] - b["Time (in sec)"]).findIndex((racer) => racer.Name === playerName) + 1
              return fastest > currPos ? currPos : fastest
            }, Number.MAX_SAFE_INTEGER)
            text = [
              "Guide to Fastest",
              "The fastest here is the fastest finishing time of current runner.",
              `It's calculated by finding the lowest time of all times. (${playerResults.length})`,
              "The mean helps understand the best performance of player."
            ];
          }
          else if (currFilter == "Mean") {
            time = playerResults.reduce((sum, curr) => sum + curr["Time (in sec)"], 0) / playerResults.length
            position = playerResults.reduce((sum, curr) => 
              sum + allRelayResults[curr.raceName].sort((a, b) => a["Time (in sec)"] - b["Time (in sec)"]).findIndex((racer) => racer.Name === playerName) + 1, 0) / playerResults.length
            genderPos = playerResults.reduce((sum, curr) => 
              sum + allRelayResults[curr.raceName].filter((racer) => racer.Gender == player.Gender).sort((a, b) => a["Time (in sec)"] - b["Time (in sec)"]).findIndex((racer) => racer.Name === playerName) + 1, 0) / playerResults.length
            text = [
              "Guide to Mean",
              "The mean here  is the average finishing time of all players.",
              `It's calculated by summing all times and dividing by the number of races. (${playerResults.length})`,
              "The mean helps understand the overall player pace and average player performance."
            ];
          }
          else {
            time = playerResults.reduce((fastest, curr) => fastest < curr["Time (in sec)"] ? curr["Time (in sec)"] : fastest, 0)
            position = playerResults.reduce((fastest, curr) => {
              const currPos = allRelayResults[curr.raceName].sort((a, b) => a["Time (in sec)"] - b["Time (in sec)"]).findIndex((racer) => racer.Name === playerName) + 1
              return fastest < currPos ? currPos : fastest
            }, 0)

            genderPos = playerResults.reduce((fastest, curr) => {
              const currPos = allRelayResults[curr.raceName].filter((racer) => racer.Gender == player.Gender).sort((a, b) => a["Time (in sec)"] - b["Time (in sec)"]).findIndex((racer) => racer.Name === playerName) + 1
              return fastest < currPos ? currPos : fastest
            }, 0)
            text = [
              "Guide to Slowest",
              "The fastest here is the slowest finishing time of current runner.",
              `It's calculated by finding the longest time of all times. (${playerResults.length})`,
              "The mean helps understand the worst performance of player."
            ];
          }
          // Return the mapped JSX
          return [[`${currFilter} Time in Seconds`, time, text], [`${currFilter} Position`, position, text], [`${currFilter} Gender Position`, genderPos, text]].map(
            (iter, index) => (
              <div key={index} className='summary-statistic-tab'>
                <div className='statistics-title-area'>
                  <div>{iter[0]}</div>
                  <div
                    className='info-button'
                    onClick={() => openModal(index + 2)} // Set the modalNo dynamically
                  >
                    i
                  </div>
                  {modalNo === index + 2 && isModalOpen && ( // Check if the modal should display for this index
                    <div className='help-modal' style={{ display: 'block' }}>
                      <div className='modal-content' ref={modalref}>
                        <span onClick={closeModal}>&times;</span>
                        <div className='modal-text'>
                          <h2>{iter[2][0]}</h2>
                          <div>{iter[2][1]}</div>
                          <div>{iter[2][2]}</div>
                          <div>{iter[2][3]}</div>
                        </div>
                      </div>
                    </div>
                  )}
                </div>
                <div className='bold-statistic'>{index == 0 ? convertSecondstoTime(iter[1]) : iter[1].toFixed(2)}</div>
              </div>
            )
          );
        })()}
      </div>
      {playerResults.length > 0 && <LinearReg playerData={playerResults}></LinearReg>}
      </div>
      <Footer></Footer>
    </div>
  )
}

export default Player;