import React from "react";
import Plot from "react-plotly.js";
import "../css/BoxPlot.css"

const BoxPlot = ({ data, gender }) => {
  return (
    <div className="box-plot-dimensions">
      <Plot
        data={[
          {
            y: data,
            type: "box",
            name: gender,
            boxpoints: "all", // Show all data points
            jitter: 0.3, // Add jitter for better visualization
            pointpos: -1.8,
            marker: { color: gender == "Male" ? "skyblue" : "lightpink" },
          },
        ]}
        layout={{
          title: `Boxplot of ${gender} Time (in sec)`,
          paper_bgcolor: "transparent", // Background of the entire chart
          plot_bgcolor: "transparent", // Background of the plot area
          yaxis: { title: "Time (in sec)" },
          width: 600,
          font: {
            color: "white", // General font color for the plot
          },
        }}
      />
    </div>
  );
};

export default BoxPlot;
